(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sw"] = {"ui":{"skip":"Ruka hadi maudhui","back":"← Rudi kwenye AI-gile","lang.button":"Lugha: {name}","lang.dialog":"Chagua lugha","lang.search":"Tafuta lugha","lang.none":"Hakuna lugha inayolingana","lang.notYet":"{name} haijatafsiriwa bado","theme.aria":"Badilisha mandhari: angavu, meusi au nyeusi tupu","theme.toLight":"Badili kwenda mandhari angavu","theme.toDark":"Badili kwenda mandhari meusi","theme.toBlack":"Badili kwenda mandhari ya rangi nyeusi tupu (nyeusi halisi, rafiki kwa skrini za OLED)","words.underline":"Pigia mstari maneno haya kwenye ukurasa","words.underlineHelp":"Weka kipanya juu ya neno lenye vitone au uliguse ili uone maana yake.","words.col.todo":"Kadi zilizochaguliwa kwa sasa: timu itaanza na hizi baadaye.","words.col.doing":"AI anafanya kazi kwenye kadi hii sasa hivi.","words.col.review":"AI mmoja amemaliza kazi; mwingine anaikagua kabla haijakufikia.","words.col.verify":"Zinakusubiri wewe: zijaribu na useme kama zinafanya kazi.","words.col.team":"Maelezo au majibu yako, yanayosubiri timu iyachukue.","words.col.done":"Imekamilika na imekubaliwa.","index.title":"AI-gile: timu yako ya AI ya wasanidi, kwenye ubao mmoja","index.description":"AI-gile ni ubao wa kanban kwa timu za AI zinazoandika msimbo. Hufanya kazi wakati umelala; wewe unapata rundo moja fupi la mambo ya kuamua, kujaribu na kukubali.","hero.logoAlt":"Ikoni ya ubao wa AI-gile","hero.h1.html":"Timu yako ya AI ya wasanidi, kwenye ubao&nbsp;mmoja.","hero.alpha":"🐣 Pre-alpha iliyofungwa","hero.alphaTitle":"Bado mapema na haijakamilika: asante kwa kujaribu!","hero.lede":"Wanajenga wakati umelala. Unaamka kukuta rundo moja fupi: maswali machache, mambo machache ya kujaribu, almasi moja au mbili za zambarau. Bofya, kubali, rudi kwenye kahawa yako.","dl.windows":"Programu ya Windows","dl.browser":"Iendeshe kwenye kivinjari","dl.messenger":"📱 Messenger kwa simu yako","dl.soon":"Inakuja hivi karibuni","dl.notify":"🔔 Niambie itakapofunguliwa","dl.notifySmall":"Alpha au beta","hero.secondary":"Agile, lakini timu haihitaji kahawa ya stand-up kamwe. (Hufanya stand-up hata hivyo.)","pitch.h2":"AI-gile kwa maneno mengi kadri upendavyo","pitch.lede":"Chagua urefu, kuanzia neno moja hadi 144. Kila urefu ni maelezo yake yenyewe, yaliyoandikwa kwa ukubwa huo. Buruta kitelezi au tumia vitufe vya mishale.","pitch.rangeLabel":"Urefu kwa maneno","pitch.dice":"🎲 toleo jingine","pitch.words.one":"neno {n}","pitch.words.other":"maneno {n}","pitch.letters.one":"herufi {n}","pitch.letters.other":"herufi {n}","pitch.chars.one":"kibambo {n}","pitch.chars.other":"vibambo {n}","count.line.html.one":"kadi {n} kwenye ubao sasa hivi","count.line.html.other":"kadi {n} kwenye ubao sasa hivi","people.humans.html.one":"👥 binadamu {n}","people.humans.html.other":"👥 binadamu {n}","people.agents.html.one":"🤖 wakala {n}","people.agents.html.other":"🤖 mawakala {n}","people.working.html.one":"⚡ {n} anafanya kazi sasa hivi","people.working.html.other":"⚡ {n} wanafanya kazi sasa hivi","pre.title":"AI-gile: kuna kitu kinajengwa","pre.description":"Kuna kitu kinajengwa hapa: ubao ambapo timu za AI zinajenga unachoomba, na kukufundisha zikiendelea. Kwa sasa ni pre-alpha iliyofungwa na marafiki.","pre.h1":"Kuna kitu kinajengwa hapa. 🤫","pre.line":"Ubao ambapo timu za AI zinajenga unachoomba, na kukufundisha zikiendelea. Kwa sasa ni pre-alpha iliyofungwa na marafiki.","pre.btn":"🔔 Niambie itakapofunguliwa","pre.peek":"Nyuma ya kioo: ubao halisi, moja kwa moja. Kila kadi ni mstari wa rangi.","pre.peekFake":"Nyuma ya kioo: hivi ndivyo ubao kazini unavyoonekana.","pre.night":"🌙 Mlinzi wa usiku ndiye msimamizi · 😴 binadamu anapumzika","features.aria":"Inafanya nini","f.pile.h":"Rundo moja kwa ajili yako","f.pile.html":"<b>Kwako</b> hushikilia kila kitu kinachokusubiri, kwenye kila mradi: maswali, mambo ya kujaribu, kazi ambazo binadamu pekee anaweza kuzifanya. Foleni yako inaonyesha kinachofuata na kitachukua muda gani.","f.sleep.h":"Timu zinazofanya kazi ukiwa umelala","f.sleep.p":"Kila mradi una kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi na timu inaamka, inafanya kazi, na kuirudisha pamoja na hatua ambazo binadamu aliyechoka anaweza kuzifuata.","f.tester.h":"Mjaribu wa AI hukagua kwanza","f.tester.p":"Kabla ya chochote kukufikia, mjaribu hufuata hatua kwenye nakala ya programu na kuonyesha alichokiona, pamoja na picha ya skrini. Pitia zile zilizofaulu na ukubali kwa bofya moja.","f.proof.h":"Ushahidi, si ahadi","f.proof.p":"Kila makabidhiano yanaonyesha kilichobadilika: faili, tofauti, picha za skrini. Huhitaji kufungua kila programu kuona kama imekamilika.","f.chat.h":"Piga gumzo na viongozi wako","f.chat.p":"Safu kama ya Discord: ikoni moja kwa kila mradi, almasi za zambarau kwa kinachokuhitaji. Mwandikie kiongozi wazo; analigeuza kuwa kadi na mpango, pamoja na kitufe cha ✅ Anza.","f.tidy.h":"Hujipanga yenyewe","f.tidy.p":"Kadi zinazohusiana huunganishwa kuwa moja, vichwa vilivyochanganyika hurekebishwa, na ukaguzi wa tokeni huweka msimbo mwepesi. Mambo machache ya kubadilisha kati yake, machache ya kufikiria.","f.private.h":"Yako, kwenye kompyuta yako","f.private.li1":"Ubao huendeshwa kwenye kompyuta yako mwenyewe na hukujibu wewe tu.","f.private.li2":"Ujumbe wa faragha kati ya watu umesimbwa kutoka mwanzo hadi mwisho.","f.private.li3":"Hakuna akaunti, hakuna vifuatiliaji, hakuna vidakuzi.","f.lang.h":"Kwa lugha yako","f.lang.p":"Zaidi ya lugha 120, kuanzia Kiholanzi, Kiwelisi na Kijapani hadi maharamia, Yoda na Kiklingoni, na kubadili haraka kurudi Kiingereza kwa maneno ya kitaalamu.","f.service.h":"Kutoka wazo hadi huduma halisi","f.service.p":"Umejenga kitu kwa AI ambacho watu sasa wanakitumia? Kiwekee alama kama huduma na ubao utakusaidia kukiendesha vizuri: ukaguzi wa upatikanaji, ukurasa wa hali wa umma, matukio yenye uchambuzi, mabadiliko yanayohitaji Go, nakala rudufu zinazokaguliwa kila siku. Msaada hukufundisha kila hatua unapoendelea.","msgr.h2":"AI-gile Messenger: timu yako mfukoni mwako","msgr.p1":"Ongea na timu yako ya AI bila kufungua ubao. Piga gumzo na viongozi wa miradi yako na marafiki zako, uone hatua za majaribio za kadi na uzijibu, yote kutoka kwenye simu yako.","msgr.p2":"Ili kuiunganisha, changanua msimbo wa QR kwenye ubao wako. Mara ya kwanza? Gumzo la onyesho la kirafiki litakuonyesha kila kitu.","msgr.when":"Android kwanza, kisha toleo la wavuti kwa simu na iPhone.","msgr.who":"Kiongozi wa mradi wako","msgr.b1":"Marekebisho ya hali ya giza yako tayari. Unataka hatua za majaribio?","msgr.b2":"Ndiyo tafadhali!","msgr.b3":"1. Fungua Mipangilio. 2. Chagua Giza. Inaonekana sawa?","tl.aria":"Ratiba ya matukio kuanzia mazungumzo ya kwanza hadi mpango wa mbele","tl.h2":"Kuanzia gumzo la kwanza hadi yajayo","tl.lede":"Tarehe na saa halisi, katika saa za eneo lako. Baada ya leo ni mpango, bila tarehe za ahadi.","tl.today":"Leo","tl.planned":"imepangwa","tl.doing":"inaendelea","tl.cards.one":"kadi {n}","tl.cards.other":"kadi {n}","join.h2":"Jiunge nasi","join.lede":"AI-gile inajengwa na mtu wa ajabu mwenye ndevu, mwenye AuDHD na mapambano kadhaa ya afya ya akili, pamoja na mawakala wengi wenye subira. Kwa sasa ni ya faragha, kwenye alpha iliyofungwa na marafiki. Ungependa kujaribu itakapofunguliwa?","join.btn":"Onyesha nia","join.small":"Tutakutumia barua pepe, hakuna kingine","footer.tag":"AI-gile. Hakuna vifuatiliaji, hakuna vidakuzi, hakuna kahawa ya stand-up.","footer.licence":"Leseni ya biashara","footer.status":"Hali","footer.privacy":"Tunachohifadhi","footer.thanks":"Simu kwa hisani ya ChilledChat","form.sending":"Inatuma…","form.failed":"Haikufanikiwa: jaribu tena baadaye.","form.offline":"Imeshindwa kufikia AI-gile: jaribu tena baadaye.","form.keep":"Tunatumia hiki tu kukujibu, kisha tunakifuta. Hakuna vifuatiliaji, hakuna vidakuzi.","form.keepLink":"Tunachohifadhi","interest.title":"AI-gile: niambie alpha itakapofunguliwa","interest.description":"Acha barua pepe yako ujue alpha au beta iliyofungwa ya AI-gile itakapofunguliwa.","interest.h1":"🔔 Niambie itakapofunguliwa","interest.lede":"AI-gile iko kwenye pre-alpha iliyofungwa. Acha barua pepe yako nasi tutakuandikia mara moja, kukiwa na nafasi kwako.","interest.email":"Barua pepe yako","interest.which":"Jaribio lipi?","interest.alpha":"Alpha iliyofungwa: mapema, changa, mabadiliko mengi","interest.beta":"Beta: thabiti zaidi, baadaye","interest.both":"Lolote, lile litakalokuja kwanza","interest.submit":"Niweke kwenye orodha","interest.thanks":"Asante! Uko kwenye orodha.","licence.title":"AI-gile: leseni ya biashara","licence.description":"Unatumia AI-gile kwenye biashara yako? Omba leseni ya biashara ya bure.","licence.h1":"📜 Leseni ya biashara","licence.lede":"Unatumia AI-gile kazini? Tuambie wewe ni nani na unafanya nini. Ikifanya mema, leseni ni bure.","licence.company":"Kampuni","licence.website":"Tovuti","licence.what":"Unachofanya","licence.how":"Inavyosaidia dunia","licence.email":"Barua pepe","licence.submit":"Omba","licence.thanks":"Asante! Tutajibu kwa barua pepe.","status.title":"Hali ya AI-gile","status.h1":"Hali ya AI-gile","status.quiet":"Kimya kabisa","status.intro":"Je, AI-gile inafanya kazi sasa hivi? Ukurasa huu hukagua tovuti, kushiriki mbao, simu na upakuaji kila baada ya dakika 5.","status.up":"Inafanya kazi (ilijibu ndani ya {ms} ms)","status.slow":"Haikujibu ukaguzi uliopita, inajaribu tena","status.down":"Haifanyi kazi: haikujibu ukaguzi wa mara mbili zilizopita","status.svc.web":"Tovuti","status.svc.web.offers":"Tovuti hii: AI-gile ni nini, na fomu ya kuonyesha nia","status.svc.boards":"Kushiriki mbao","status.svc.boards.offers":"Mbao za umma, ujumbe kati ya marafiki na mialiko","status.svc.calls":"Simu","status.svc.calls.offers":"Sauti, video na kushiriki skrini ndani ya AI-gile","status.svc.download":"Upakuaji","status.svc.download.offers":"Kisakinishi cha Windows na viungo vya mialiko","status.checking":"Inakagua…","status.offline":"Huduma ya hali haipatikani sasa hivi (inajaribu tena)","status.updated":"imesasishwa {ago}","status.justNow":"sasa hivi","status.min":"dakika {n} zilizopita","status.hours":"saa {n} zilizopita","status.days":"siku {n} zilizopita","privacy.title":"AI-gile: tunachohifadhi","privacy.h1":"Tunachohifadhi","privacy.lede":"Kwa kifupi: ni kile unachotutumia tu, na si kwa muda mrefu.","privacy.only":"Ni kile unachotutumia tu: unachoandika kwenye fomu, kama barua pepe yako. Hakuna kingine kukuhusu.","privacy.sealed":"Kinafungwa kwa muhuri ili seva yetu isiweze kukisoma: kwenye kivinjari chako kabla hakijaondoka (kwenye kivinjari cha zamani, mara tu kinapofika). Ni ubao wetu pekee unaoweza kukifungua.","privacy.server":"Kinafutwa kwenye seva mara tu kinapofika kwenye ubao wetu. Chochote kinachobaki huko baada ya siku 30 kinafutwa hata hivyo.","privacy.board":"Tunakihifadhi kwenye ubao wetu hadi tutakapokujibu tu, kisha tunakifuta huko pia.","privacy.none":"Hakuna vifuatiliaji, hakuna vidakuzi, hakuna takwimu za matumizi.","privacy.local":"Lugha yako na chaguo lako la mwanga au giza hubaki kwenye kivinjari chako. Havitumwi kwetu kamwe.","privacy.ask":"Ungependa kifutwe mapema zaidi? Jibu barua pepe yetu na utuambie.","live.h2":"Itazame ikijengwa, moja kwa moja","live.caption":"Kila kadi imefichwa: unaona umbo la kazi, si maneno.","live.watching.one":"moja kwa moja: {n} wanatazama","live.watching.other":"moja kwa moja: {n} wanatazama","live.last.now":"Kadi ya mwisho ilihamishwa muda mfupi uliopita","live.last.min.one":"Kadi ya mwisho ilihamishwa dakika {n} iliyopita","live.last.min.other":"Kadi ya mwisho ilihamishwa dakika {n} zilizopita","live.last.hour.one":"Kadi ya mwisho ilihamishwa saa {n} iliyopita","live.last.hour.other":"Kadi ya mwisho ilihamishwa saa {n} zilizopita","live.last.day.one":"Kadi ya mwisho ilihamishwa siku {n} iliyopita","live.last.day.other":"Kadi ya mwisho ilihamishwa siku {n} zilizopita","live.offline":"Ubao wa moja kwa moja unapumzika kidogo. Rudi tena hivi karibuni.","live.cols":"Backlog|Za kufanya|Zinaendelea|Timu inakagua|Zako za kujaribu|Kwa timu|Zimekamilika"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Kukabidhi."]},{"n":2,"texts":["Kanban, kiotomatiki.","Mawakala, wamepangika.","Mawazo, yamejengwa."]},{"n":3,"texts":["Kanban ya roboti.","Mawazo yanakuwa vipengele.","Kanban ya mawakala, bure."]},{"n":5,"texts":["Ubao wa kanban unaoendeshwa na mawakala.","Wewe andika kadi. Mawakala wanajenga.","Bure, binafsi, imejaribiwa, kidogo kichekesho."]},{"n":8,"texts":["Ubao wa bure wa kanban wenye mawakala wa AI.","Andika wazo. Mawakala wanalijenga. Wewe unakubali.","Agile kwa binadamu mmoja na roboti wengi wenye subira."]},{"n":13,"texts":["Ubao wa kanban kwenye kompyuta yako ambapo mawakala wa AI huchukua kadi na kujenga.","Andika wazo. Timu ya mawakala inalijenga. Mjaribu analikagua, kisha wewe unaamua.","Bure, bila akaunti wala vifuatiliaji: ubao, roboti kadhaa, na wewe ukiwa kiongozi."]},{"n":21,"texts":["AI-gile ni ubao wa kanban wa kufanya kazi na mawakala wa AI wanaoandika msimbo. Wao huchukua kadi; wewe unazijaribu na kuzikubali.","Kila mradi unapata kiongozi na timu ya mawakala wa AI. Toa maoni kwenye kadi yoyote na timu inaanza kazi.","Ubao wa majukumu wa bure na binafsi unaoendeshwa kwenye kompyuta yako mwenyewe. Wafanyakazi ni roboti. Anayesema ndiyo ni wewe."]},{"n":34,"texts":["Unaweka mawazo kwenye ubao. Timu ya mawakala wa AI inayageuza kuwa vipengele vinavyofanya kazi, inavijaribu, na kukurudishia pamoja na hatua za kujaribu. Hakuna kinachohesabiwa kuwa kimekamilika hadi useme.","AI-gile ni ubao wa kanban uliotengenezwa nyumbani ambao Rich aliujenga kwa msaada mkubwa wa mawakala anaowasimamia sasa. Ni wa bure, huendeshwa kwenye kompyuta yako, na hushirikiwa na marafiki, hauuzwi.","Fikiria ubao wa kawaida wa kanban, wenye safu kutoka Backlog hadi Zimekamilika, isipokuwa kadi zinachukuliwa na mawakala wa AI. Wanaripoti maendeleo, wanauliza wanapokwama, na daima wanasubiri kidole chako gumba juu."]},{"n":55,"texts":["AI-gile ni ubao wa kanban ambapo timu inaundwa na mawakala wa AI. Kila mradi una kiongozi anayepanga kazi na wasaidizi wanaojenga. Kipengele kikiwa tayari, mjaribu wa AI analijaribu na kupiga picha ya skrini, kisha kinatua kwenye rundo lako. Kikubali, au toa maoni nao wakifanyie kazi upya.","Ilianza kama njia ya mtu mmoja ya kufuatilia vikao vingi vya AI vya kuandika msimbo kwa wakati mmoja, kisha ikakua kuwa ubao kamili. Inaendeshwa kwenye kompyuta yako, haihitaji akaunti, na haina vifuatiliaji. Ni ya bure kwa marafiki na wadadisi. Pia haijakamilika, kwa hiyo tarajia kasoro na mshangao mara moja moja.","Hili hapa toleo la ukweli. Bado ni wewe unayehitaji kuwa na mawazo, na bado ni wewe unayekagua matokeo. AI-gile hufanya kila kitu kilicho katikati: huweka kadi kwa mpangilio, huamsha wakala sahihi unapotoa maoni, huonyesha hasa kilichobadilika, na hukusanya yote kwenye rundo moja fupi kwa ajili yako."]},{"n":89,"texts":["AI-gile ni ubao wa kanban wa bure unaouendesha kwenye kompyuta yako mwenyewe. Badala ya watu, kila mradi una timu ya mawakala wa AI: kiongozi anayegeuza mawazo yako kuwa kadi na mpango, na wasaidizi wanaochukua kadi kwa mpangilio wa kipaumbele. Kitu kikijengwa, mjaribu wa AI hufuata hatua za majaribio na kukuonyesha alichokiona. Kisha kinasubiri kwenye rundo moja liitwalo Kwako. Unakikubali, au unatoa maoni na timu inajaribu tena. Hakuna kitu kinachofika Zimekamilika bila wewe.","Kuna mambo kadhaa ambayo huenda hukuyatarajia. Mlinzi wa usiku hujaza safu ya Za kufanya ukiwa umelala, akichagua kadi zisizohitaji jibu kutoka kwako. Kihesabu cha tokeni kinaonyesha mawakala wametumia kiasi gani leo na wiki hii, na No Token Mode huwaambia waache kutumia. Unaweza kuwatumia marafiki ujumbe, na ujumbe wa faragha umesimbwa kutoka mwanzo hadi mwisho. Ubao huzungumza takriban lugha 120, zikiwemo Kiholanzi, Kiflemi, maharamia na Kiklingoni. Hakuna hata kimoja kinachogharimu senti, na hakuna anayejaribu kukuuzia chochote pia.","AI-gile ni mradi mdogo, binafsi, si kampuni. Rich alitaka kutunza miradi kadhaa ya AI ya kuandika msimbo bila kufungua kila programu kuangalia hali, kwa hiyo yeye na mawakala wakajenga ubao kwa ajili hiyo, kisha wakautumia ubao huo kujenga sehemu iliyobaki yake. Uko kwenye pre-alpha iliyofungwa, yaani unafanya kazi, kwa kiasi kikubwa, kwa marafiki wachache. Hakuna ukurasa wa bei, hakuna jarida na hakuna mpango wa kukua. Ukionekana kukufaa, unaweza kuomba kujaribu utakapofunguliwa zaidi kidogo."]},{"n":144,"texts":["AI-gile ni ubao wa kanban kwa binadamu mmoja na mawakala wengi wa AI. Unaendeshwa kwenye kompyuta yako mwenyewe na ni wa bure kabisa. Unaongeza miradi, na kila mradi unapata kiongozi na timu ndogo. Unapiga gumzo na kiongozi, kama vile Discord, na kueleza wazo; kiongozi analigeuza kuwa kadi na mpango, kisha anasubiri ubonyeze Anza. Timu inapitia kadi kwa mpangilio wa kipaumbele, ikitumia zana rahisi ya mstari wa amri iliyotengenezwa kwa miundo ya lugha. Kabla chochote hakijakurudia, mjaribu wa AI hufuata hatua kwenye nakala ya programu na kuambatisha picha ya skrini. Kazi iliyokamilika inatua kwenye rundo lako pamoja na faili zilizobadilika na tofauti. Unaikubali, au unaacha maoni na timu inaamka na kujaribu tena. Wewe pekee ndiye unayeweza kuhamisha kadi hadi Zimekamilika.","Siku moja na AI-gile, kwa ufupi. Jioni unaacha maoni machache: kitufe hiki kiko mahali pasipofaa, orodha ile ipangwe, tunaweza kupata hali ya giza. Unaenda kulala. Mawakala wanasoma maoni, wanafanya mabadiliko, wanayajaribu na kukurudishia. Za kufanya zikiisha, mlinzi wa usiku anazijaza kutoka kwenye backlog kwa kadi zisizohitaji jibu lako. Asubuhi kuna rundo moja fupi: maswali machache na mambo kadhaa ya kujaribu, kila moja likiwa na hatua ambazo mtu mwenye usingizi anaweza kuzifuata na picha ya skrini inayoonyesha inafanya kazi. Unapitia, unakubali nzuri na kurudisha zilizobaki. Kihesabu cha tokeni kinaonyesha yote yalitumia kiasi gani, na No Token Mode ipo kwa wiki za kubana matumizi. Kisha unakula kifungua kinywa, ambapo mawakala bado hawawezi kusaidia. Wakati mwingine unaamka na swali la wakala aliyekwama, na unalijibu kwa sentensi moja kabla ya chai. Hakuna mkutano, hakuna barua pepe ndefu, hakuna kuuliza nani alibadilisha nini.","Kwanza, AI-gile si nini. Si kampuni changa, haiuzwi, na hakuna anayekusanya data yako. Ni ubao wa bure unaoendeshwa kwenye kompyuta yako, bila akaunti, bila vifuatiliaji na bila vidakuzi. Ni nini: mahali pamoja pa nadhifu pa kuona miradi yako yote ya AI ya kuandika msimbo kwa wakati mmoja, timu ya mawakala ikifanya kadi na wewe ukifanya maamuzi. Huunganisha kadi zinazohusiana, hurekebisha vichwa vilivyochanganyika, na hufuatilia jinsi msimbo unavyobaki mwepesi. Huzungumza takriban lugha 120, kuanzia Kiholanzi na Kiflemi hadi maharamia na Kiklingoni. Marafiki wanaweza kutumiana ujumbe, kwa faragha na kwa usimbaji. Ilijengwa na Rich na idadi kubwa ya mawakala wenye subira, hasa kwa kujitumia yenyewe. Iko kwenye pre-alpha iliyofungwa, kwa hiyo ina kasoro hapa na pale. Ukiona inavutia, omba kwa adabu na huenda ukaingia mapema."]}],"quips":{"1":"Neno moja. Jasiri. Labda jasiri kupita kiasi.","3":"Maneno matatu. Tayari ni ya kweli kuliko kurasa nyingi za bidhaa.","8":"Maneno manane. Bado ni mafupi kuliko stand-up.","21":"Kwa njia, urefu ni story points. Bila shaka ndivyo.","55":"Maneno hamsini na tano. Kadi mbili zimekamilika ulipokuwa unasoma hili.","144":"Hii ndiyo ndefu. Hakuna 233. Mawakala wamekwenda kulala."}},"timeline":{"first-idea.name":"Wazo la kwanza","first-idea.line":"Mazungumzo ya kwanza kabisa, kabla msimbo wowote haujakuwepo.","first-board.name":"Ubao wa kwanza","first-board.line":"Ubao unaofuatilia ujenzi wake wenyewe: kadi, safu, buruta na dondosha, miradi.","team-roles.name":"Timu na majukumu","team-roles.line":"Wasifu wa mawakala, violezo vya timu, nafasi na nani anafanya nini.","install.name":"Usakinishaji na matoleo","install.line":"Zip ambayo rafiki anaweza kusakinisha, kujisasisha, njia za matoleo na kurudi nyuma.","usage-saver.name":"Kiokoa matumizi","usage-saver.line":"Pima gharama za uendeshaji, weka msimbo mwepesi, okoa kikomo chako.","friends.name":"Marafiki na kushiriki","friends.line":"Ujumbe wa faragha, relay iliyosimbwa, mialiko, majukumu na miradi ya pamoja.","languages.name":"Lugha","languages.line":"Kila maandishi ya skrini kwenye faili la lugha, Kiholanzi na Kiflemi kwanza.","ai-tester.name":"Mjaribu wa AI","ai-tester.line":"Mjaribu hukagua kila makabidhiano kwanza na kuonyesha alichokiona.","website.name":"Tovuti","website.line":"aigile.lol, ukurasa wa utangulizi na ratiba hii.","streaming.name":"Gumzo na utiririshaji","streaming.line":"Discord, Twitch, OBS, hali ya mtiririshaji, GIF na emoji.","no-ai.name":"Toleo bila AI","no-ai.line":"Ubao kwa watu wanaoandika msimbo bila AI, na mbao za umma.","night-watch.name":"Mlinzi wa usiku","night-watch.line":"Mlinzi na Scrum Master huweka timu kwenye kazi ukiwa umelala.","p-more.name":"Mengine yote","p-more.line":"Mawazo madogo yanayosubiri zamu yake.","p-android.name":"Simu na Android","p-android.line":"Fikia ubao wako kutoka kwenye simu, kisha programu asilia ya Android.","p-release.name":"Alpha na zaidi","p-release.line":"Alpha iliyofungwa, tovuti hai, kisha beta.","p-languages.name":"Lugha zaidi","p-languages.line":"Lugha 130, na hali ya kujizamisha kwa wanaojifunza lugha.","p-engines.name":"Injini zaidi za AI","p-engines.line":"Chagua Claude, Codex, Gemini, Copilot au Cursor kwa kila wakala.","p-pro.name":"Mazoea ya kitaalamu","p-pro.line":"Lebo za hatari, milango ya kuunganisha, kadi za matukio na vizuizi vya usalama.","p-self.name":"Kukutunza wewe","p-self.line":"Hali ya uchovu, vikumbusho vya kujitunza na 4:20.","p-servers.name":"Seva na ukuaji","p-servers.line":"Mipangilio ya seva ya kimataifa, majukumu na kupanga ukuaji.","p-livestream.name":"Ziada za utiririshaji","p-livestream.line":"Gumzo la Twitch, emoji maalum na mwonekano wa umma wa moja kwa moja."},"words":{"button":"📖 Maneno ya kitaalamu","h":"📖 Maneno yaliyoelezwa","intro":"Mafunzo ya bure kwa lugha rahisi: kila neno utakalokutana nalo kutoka wazo la kwanza hadi huduma wanayoitegemea watu, pamoja na Agile, ujenzi, kuiweka salama na kufanya kazi na AI njiani.","search":"Tafuta neno…","none":"Hakuna neno linalolingana.","close":"Funga","count":{"one":"neno {count}","other":"maneno {count}"},"groups":[{"id":"idea","name":"💡 Wazo na ugunduzi"},{"id":"plan","name":"🗺️ Kupanga kazi"},{"id":"agile","name":"🔁 Njia za kufanya kazi za Agile"},{"id":"build","name":"🛠️ Kujenga"},{"id":"test","name":"🧪 Kupima na ubora"},{"id":"change","name":"🔀 Kubadilisha kwa usalama"},{"id":"run","name":"🛎️ Kuendesha huduma"},{"id":"sec","name":"🔒 Usalama na faragha"},{"id":"ai","name":"🤖 Kufanya kazi na AI"},{"id":"money","name":"💰 Pesa na leseni"}],"list":[{"id":"discovery","g":"idea","word":"Ugunduzi (Discovery)","text":"Hatua ya mwanzo ya kujua ni tatizo gani linafaa kutatuliwa na kwa ajili ya nani, kabla ya kujenga chochote.","also":["hatua ya ugunduzi","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Taarifa ya tatizo","text":"Sentensi moja au mbili zinazosema nani ana tatizo, ni nini, na kwa nini ni muhimu, ili kila mtu alenge jambo moja.","also":["taarifa za tatizo","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Mtumiaji","text":"Mtu anayetumia unachojenga. Mahitaji yake ndiyo sababu ya kazi.","also":["watumiaji","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Mdau","text":"Yeyote anayejali matokeo ya kazi au anayeathiriwa nayo, kama wanaolipia, wanaoitumia au wanaoisaidia.","also":["wadau","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Mhusika mfano (Persona)","text":"Mtu wa kubuni lakini anayefanana na mtu halisi, anayewakilisha aina moja ya mtumiaji, ili timu iweze kuuliza “je, Sam angeona hii rahisi?”","also":["wahusika mfano","persona","personas"]},{"id":"userresearch","g":"idea","word":"Utafiti wa watumiaji","text":"Kuzungumza na kuwatazama watu halisi ili kujua wanachohitaji, badala ya kukisia.","also":["mahojiano ya watumiaji","user research","user interviews"]},{"id":"journey","g":"idea","word":"Safari ya mtumiaji","text":"Hatua anazopitia mtu kukamilisha jambo, tangu aliposikia kulihusu hadi kulimaliza, pia nje ya bidhaa yako. Kuzichora kunaonyesha mahali wanapokwama.","also":["safari za watumiaji","safari ya mteja","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Kero (Pain point)","text":"Kitu kinachowakera au kuwachelewesha watu leo. Bidhaa nzuri huondoa kero.","also":["kero","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Dhana","text":"Kitu unachoamini lakini hujakithibitisha bado. Kuandika dhana kunaonyesha cha kujaribu kwanza.","also":["assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Nadharia tete (Hypothesis)","text":"Ubashiri bora unaopanga kuuthibitisha, pamoja na unachotarajia kitokee, kama “watu watajisajili ikiwa mwezi wa kwanza ni bure”.","also":["nadharia tete","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Jaribio (Experiment)","text":"Jaribio dogo lililopangwa ili kujua kama wazo linafanya kazi, kabla ya kuwekeza sana ndani yake.","also":["experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Uthibitisho wa dhana (PoC)","text":"Jaribio la haraka, lisilo kamilifu, kuona kama wazo linaweza kufanya kazi hata kidogo. Kwa kawaida hutupwa mara unapopata jibu.","also":["PoC","proof of concept","uthibitisho wa dhana"]},{"id":"prototype","g":"idea","word":"Mfano wa awali (Prototype)","text":"Mfano wa mapema wa bidhaa, mara nyingi picha unazoweza kubonyeza, wa kujaribisha wazo kwa watu kabla ya kulijenga ipasavyo.","also":["mifano ya awali","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Mchoro wa mpangilio (Wireframe)","text":"Mchoro rahisi wa skrini unaoonyesha vitu vitakaa wapi, bila rangi wala maudhui halisi.","also":["wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mfano wa mwonekano (Mockup)","text":"Picha ya kina ya jinsi skrini itakavyoonekana, yenye rangi na maandishi halisi, lakini bado hakuna kinachofanya kazi.","also":["mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Hoja ya kibiashara","text":"Sababu za kufanya mradi: unagharimu kiasi gani, unaleta au unaokoa nini, na hatari zake.","also":["hoja za kibiashara","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Uwezekano wa kutekelezeka","text":"Kama kitu kinaweza kweli kujengwa na kutunzwa kwa muda, pesa na ujuzi ulio nao.","also":["feasibility"]},{"id":"outcome","g":"idea","word":"Matokeo (Outcome)","text":"Mabadiliko unayotaka kwa watu, kama watu wachache zaidi kukosa miadi yao. Ni muhimu kuliko kiasi unachojenga.","also":["outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Kilichozalishwa (Output)","text":"Kitu ambacho timu hutengeneza, kama skrini mpya au ripoti. Kukitengeneza hakumaanishi moja kwa moja kwamba kinamsaidia mtu.","also":["vilivyozalishwa","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Kipimo cha mafanikio","text":"Namba inayokuambia kama kazi ilifanikisha kusudi lake, kama watu zaidi kukamilisha oda zao.","also":["vipimo vya mafanikio","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Kiashiria muhimu cha utendaji (KPI)","text":"Namba muhimu unayoifuatilia kuona kama mambo yanaenda vizuri, kama idadi ya wanaojisajili kwa wiki.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Malengo na matokeo muhimu (OKR)","text":"Njia ya kuweka malengo: lengo linasema unachotaka, na matokeo machache muhimu ni namba zinazoonyesha umefika.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Bidhaa","text":"Kitu kinachojengwa na kutunzwa kwa ajili ya watumiaji wake, kama programu, tovuti au zana.","also":["product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Dira ya bidhaa","text":"Maelezo mafupi ya nani bidhaa inamsaidia na inakoelekea baadaye.","also":["dira","vision statement","product vision"]},{"id":"po","g":"plan","word":"Mmiliki wa bidhaa (PO)","text":"Mtu anayeamua nini kijengwe na kwa mpangilio gani, ili timu ifanye kazi kila mara kwenye lililo muhimu zaidi. Kwenye AI-gile huyo ni wewe.","also":["PO","product owner","product owners","wamiliki wa bidhaa"]},{"id":"pm","g":"plan","word":"Meneja wa bidhaa (PM)","text":"Mtu anayesimamia mwelekeo wa bidhaa: inatatua matatizo gani, kwa ajili ya nani na kwa nini. PM inaweza pia kumaanisha meneja wa mradi, kwa hiyo hakikisha ni ipi.","also":["PM","product manager","product managers","mameneja wa bidhaa"]},{"id":"projmgr","g":"plan","word":"Meneja wa mradi","text":"Mtu anayeshikilia mradi uende kwa wakati na ndani ya bajeti, akifuatilia nani anafanya nini na lini.","also":["mameneja wa mradi","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Ramani ya njia (Roadmap)","text":"Mpango wa jumla wa kitakachokuja kwa miezi ijayo, kwa mpangilio. Unaonyesha mwelekeo, si tarehe kamili, na hubadilika kadiri unavyojifunza.","also":["roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Hatua muhimu (Milestone)","text":"Kituo katika mradi kinachostahili kuwekewa alama, kama “toleo la kwanza liko hewani” au “watumiaji 100”.","also":["hatua muhimu","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Bidhaa ndogo kabisa inayofaa (MVP)","text":"Toleo dogo kabisa la bidhaa ambalo bado lina manufaa kwa watu halisi, ili ujifunze kutoka kwao mapema.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Hitaji","text":"Kitu ambacho bidhaa iliyokamilika lazima ifanye au iwe.","also":["requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Wigo wa kazi (Scope)","text":"Kinachojumuishwa kwenye kazi na, kwa umuhimu uleule, kisichojumuishwa.","also":["wigo","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Wigo kupanuka (Scope creep)","text":"Pale vitu zaidi na zaidi vinapoongezwa kwenye kazi kidogo kidogo, bila mtu kukubaliana kuhusu muda au gharama ya ziada, kiasi kwamba haimaliziki kamwe.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Kipengele","text":"Kitu kimoja ambacho bidhaa inaweza kuwafanyia watu, kama “weka upya nenosiri lako”.","also":["vipengele","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic (kazi kubwa)","text":"Kipande kikubwa cha kazi, kikubwa mno kufanywa kwa mkupuo, kwa hiyo hugawanywa kuwa kadi ndogo.","also":["epic","epics"]},{"id":"story","g":"plan","word":"Hadithi ya mtumiaji (User story)","text":"Kipande kidogo cha kazi kilichoandikwa kwa upande wa mtumiaji: “Kama mnunuzi, nataka kuhifadhi kikapu changu, ili nimalize baadaye.” Huanzisha mazungumzo kuhusu nini kijengwe.","also":["hadithi za watumiaji","user story","user stories"]},{"id":"ac","g":"plan","word":"Vigezo vya kukubalika (AC)","text":"Ukaguzi ambao kadi moja lazima ipite ili ihesabiwe imekamilika, uliokubaliwa kabla kazi haijaanza, kama “kikapu bado kipo baada ya kutoka na kuingia tena”.","also":["AC","acceptance criteria","vigezo vya kukubalika"]},{"id":"task","g":"plan","word":"Jukumu","text":"Kazi moja ya kufanywa, mara nyingi hatua moja ndogo ya hadithi kubwa zaidi.","also":["majukumu","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiketi","text":"Neno jingine la kadi: kipande kimoja cha kazi au ombi moja, linalofuatiliwa tangu mwanzo hadi mwisho.","also":["ticket","tickets"]},{"id":"priority","g":"plan","word":"Kipaumbele","text":"Jinsi kitu kilivyo muhimu au cha dharura ikilinganishwa na vingine vyote, ili kazi muhimu zaidi ianze kwanza.","also":["vipaumbele","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Kupanga kipaumbele","text":"Kupanga kazi kwa mpangilio wa umuhimu. Njia maarufu ni MoSCoW: Must have (lazima), Should have (inafaa), Could have (ingefaa), Won’t have (si awamu hii).","also":["kuweka vipaumbele","prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Makadirio","text":"Makisio bora ya ukubwa wa kazi au muda itakaochukua. Ni makisio tu, si ahadi.","also":["kukadiria","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Pointi za hadithi (Story points)","text":"Njia ya kukisia ukubwa wa kazi kwa kulinganisha kadi (“takriban mara mbili ya ile”) badala ya kutumia saa. Si za kulinganisha timu.","also":["story points","story point"]},{"id":"tshirt","g":"plan","word":"Ukubwa wa fulana (T-shirt sizing)","text":"Kukisia ukubwa wa kazi kama S, M, L au XL. Ni ya haraka na inatosha kwa mipango ya mwanzo.","also":["t-shirt sizes","t-shirt sizing"]},{"id":"poker","g":"plan","word":"Poka ya kupanga (Planning poker)","text":"Mchezo wa kukadiria: kila mtu anaonyesha kadi ya ukubwa kwa wakati mmoja, kisha wa juu zaidi na wa chini zaidi hueleza kwa nini.","also":["planning poker","Scrum poker"]},{"id":"dependency","g":"plan","word":"Utegemezi","text":"Pale kazi moja haiwezi kuanza au kuisha hadi nyingine iishe.","also":["tegemezi","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Kikwazo","text":"Chochote kinachozuia kazi kusonga mbele sasa hivi, kama jibu linalokosekana au zana iliyoharibika.","also":["vikwazo","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Tarehe ya mwisho","text":"Tarehe ambayo kitu lazima kiwe kimekamilika.","also":["mwisho wa muda","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Kinachokabidhiwa","text":"Kitu halisi ambacho kazi inazalisha na kukabidhi, kama ukurasa unaofanya kazi au ripoti.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Utabiri","text":"Ubashiri wa kinachoweza kutokea, kama kazi itaisha lini, kulingana na unachojua hadi sasa.","also":["tabiri","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Kipimo","text":"Chochote unachopima na kufuatilia kadiri muda unavyopita, kama idadi ya wageni wa ukurasa au muda wa kurekebisha tatizo.","also":["vipimo","metric","metrics"]},{"id":"feedback","g":"plan","word":"Mrejesho (Feedback)","text":"Wanachokuambia watu kuhusu kazi yako, nzuri na mbaya. Kuyapata mapema na mara kwa mara ndiyo moyo wa Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Orodha ya kusubiri ya mawazo na kazi ambazo bado hazijapangwa, la muhimu zaidi likiwa juu. Hakuna kinachofanyiwa kazi huko hadi kihamie Za kufanya."},{"id":"sprint","g":"agile","word":"Sprint","text":"Kipindi kifupi cha kazi chenye kikomo (mara nyingi wiki moja au mbili, kamwe si zaidi ya mwezi mmoja) chenye lengo na seti iliyokubaliwa ya kadi za kumaliza.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Mkutano mfupi wa kila siku: kile ambacho kila mwanatimu amefanya, atakachofanya baadaye, na kinachomzuia. Kwenye Scrum huitwa daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","mkutano wa kila siku"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Njia ya kufanya kazi ambapo kadi husogea kwenye safu za ubao (kama Za kufanya, Zinaendelea, Zimekamilika) na timu hupunguza kiasi kinachoendelea kwa wakati mmoja, ili kazi iendelee kutiririka."},{"id":"wip","g":"agile","word":"Kikomo cha WIP","text":"WIP ni kifupi cha work in progress (kazi inayoendelea). Kikomo cha WIP ni idadi kubwa zaidi ya kadi ambazo safu inapaswa kubeba kwa wakati mmoja, ili timu imalize vitu kabla ya kuanza vingine.","also":["WIP"]},{"id":"dod","g":"agile","word":"Maana ya Imekamilika","text":"Orodha fupi ya timu ya maana ya “imekamilika”, kama imejaribiwa na kuelezwa, kabla kadi haijakabidhiwa kwako. Pacha wake, Maana ya Tayari, husema lini kadi iko wazi vya kutosha kuanza.","also":["Definition of Ready","DoD","DoR","Definition of Done"]},{"id":"retro","g":"agile","word":"Retro","text":"Kuangalia nyuma mara kwa mara jinsi timu inavyofanya kazi, ili kukubaliana mambo moja au mawili ya kufanya vizuri zaidi wakati ujao. Kifupi cha retrospective. Kwenye AI-gile, retro hupendekeza badiliko kwa njia za kazi za timu, nawe unasema Go au Bado.","also":["retros","retrospective","kuangalia nyuma"]},{"id":"swarm","g":"agile","word":"Kundi","text":"Wote kwa pamoja: watu wengi huacha kazi nyingine kurekebisha jambo moja la dharura pamoja hadi litatuliwe. Kwenye AI-gile kila timu husaidia mradi mmoja, na miradi mingine husubiri kwa wakati huo.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Kwenye Scrum, mtu anayesaidia timu kufanya kazi vizuri: huondoa vizuizi vyao, huhakikisha mikutano inaenda sawa na hufundisha tabia nzuri, bila kumwamrisha yeyote. Kwenye AI-gile, Lead Scrum Master hutambua kadi zilizokwama, huhimiza timu na hukukumbusha kinachosubiri, katika kila mradi.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Njia ya kufanya kazi kwa hatua ndogo: jenga kidogo, onyesha matokeo halisi mara kwa mara, jifunze kutokana na wanayosema watu na ubadilishe mpango unapoendelea, badala ya kupanga kila kitu mwanzoni.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto (Ilani ya Agile)","text":"Tamko fupi lililoandikwa mwaka 2001 na watengenezaji wa programu. Linaweka watu, matokeo yanayofanya kazi, ushirikiano wa karibu na wateja na kukabiliana na mabadiliko mbele ya mipango mizito na makaratasi.","also":["ilani ya Agile","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall (maporomoko)","text":"Njia ya zamani ya kufanya kazi: panga kila kitu, kisha jenga vyote, kisha pima vyote, hatua moja baada ya nyingine. Kubadilisha mambo katika hatua za mwisho ni kugumu na ghali.","also":["waterfall model","mfumo wa maporomoko"]},{"id":"iteration","g":"agile","word":"Mzunguko (Iteration)","text":"Raundi moja ya kujenga kitu, kukikagua na kukiboresha. Kazi ya Agile ni mfululizo wa mizunguko hii, na sprint ni aina moja yake.","also":["mizunguko","iteration","iterations"]},{"id":"increment","g":"agile","word":"Nyongeza (Increment)","text":"Kipande kipya kinachofanya kazi kinachoongezwa kwenye bidhaa katika sprint au raundi ya kazi, na kinachoendana na kilichokuwepo.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Njia maarufu ya Agile ya kufanya kazi: timu ndogo hufanya kazi kwa sprint fupi kuelekea lengo, kwa majukumu yaliyowekwa na mikutano michache ya kawaida ya kupanga, kukagua na kuboresha."},{"id":"scrumteam","g":"agile","word":"Timu ya Scrum","text":"Kikundi kidogo kinachofanya kazi katika Scrum: mmiliki wa bidhaa, Scrum Master na watengenezaji.","also":["timu za Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Matukio ya Scrum","text":"Mikutano ya kawaida katika Scrum: kupanga sprint, scrum ya kila siku, mapitio ya sprint na retro. Watu wengi huiita ceremonies.","also":["ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Kupanga sprint","text":"Mkutano mwanzoni mwa sprint ambapo timu hukubaliana kwa nini sprint ni muhimu, kadi zipi za kuchukua na jinsi ya kuanza.","also":["mkutano wa kupanga","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Lengo la sprint","text":"Sentensi moja inayosema sprint ni ya nini. Kazi ndogo zinaweza kubadilika njiani, mradi lengo linatimizwa.","also":["malengo ya sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog ya sprint","text":"Kadi zilizochaguliwa kwa sprint ya sasa, pamoja na mpango wa timu wa kuzifanya.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog ya bidhaa","text":"Orodha kamili iliyopangwa ya kila kitu kinachoweza kujengwa kwa ajili ya bidhaa, cha muhimu zaidi kikiwa juu. Hubadilika kadiri unavyojifunza.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Lengo la bidhaa","text":"Matokeo makubwa zaidi ambayo bidhaa inayaelekea, yanayoisaidia timu kuchagua la kufanya baadaye.","also":["malengo ya bidhaa","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Kuboresha backlog","text":"Kupitia backlog mara kwa mara kupanga vizuri, kugawa, kuweka mpangilio na kuongeza maelezo kwenye kadi, ili ziwe tayari kuchukuliwa. Pia huitwa backlog grooming.","also":["backlog refinement","backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Mapitio ya sprint","text":"Mkutano mwishoni mwa sprint ambapo timu huonyesha kilichokamilika na kusikia watu wanavyofikiri, ili kuamua kinachofuata.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Onyesho (Demo)","text":"Kuonyesha kazi iliyokamilika ikifanya kazi, moja kwa moja, kwa watu walioiomba.","also":["maonyesho","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Kikomo cha muda (Timebox)","text":"Kiasi kilichowekwa cha muda kwa jambo fulani. Muda ukiisha unasimama, hata kama si kila kitu kimekamilika.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Kasi ya timu (Velocity)","text":"Kiasi cha kazi ambacho timu kwa kawaida hukamilisha katika sprint, kinachotumika kupanga kiasi cha kuchukua wakati ujao. Si alama ya kiasi gani watu wanajituma.","also":["velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Uwezo wa timu","text":"Kiasi cha kazi ambacho timu inaweza kuchukua katika kipindi, baada ya likizo na majukumu mengine.","noTip":1},{"id":"burndown","g":"agile","word":"Chati ya kazi inayopungua (Burndown)","text":"Chati ya kazi iliyobaki katika sprint ikishuka siku baada ya siku. Mstari ukibaki tambarare, kuna kitu kimekwama.","also":["burndown","burndown chart","burn-down chart"]},{"id":"burnup","g":"agile","word":"Chati ya kazi inayoongezeka (Burnup)","text":"Chati ya kazi iliyokamilika ikipanda kadiri muda unavyopita, kando ya jumla iliyopangwa, ili uone utafika lini.","also":["burnup","burnup chart","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Ubao wa Kanban","text":"Ubao wenyewe: safu kwa kila hatua ya kazi, na kadi zikisogea kutoka safu moja hadi nyingine.","also":["Kanban board","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Mfumo wa kuvuta (Pull system)","text":"Njia ya kufanya kazi ambapo kazi mpya huanza tu pale mtu anapokuwa na nafasi ya kuichukua, badala ya kusukumiwa mtu ambaye tayari ana mengi.","also":["pull system","pull-based"]},{"id":"flow","g":"agile","word":"Mtiririko (Flow)","text":"Jinsi kazi inavyosonga kwenye ubao bila kukwama. Mtiririko mzuri unamaanisha kadi zinaendelea kusonga badala ya kurundikana.","also":["mtiririko wa kazi","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Muda wa ombi hadi kukamilika (Lead time)","text":"Inachukua muda gani tangu mtu aombe kitu hadi kikamilike.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Muda wa mzunguko (Cycle time)","text":"Kadi inachukua muda gani tangu kazi ianze kweli juu yake hadi ikamilike.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Idadi inayokamilika (Throughput)","text":"Idadi ya kadi zinazokamilika kwa wiki, au kwa muda wowote uliowekwa.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Kizuizi cha mtiririko (Bottleneck)","text":"Hatua moja ambapo kazi hurundikana na kupunguza kasi ya kila kitu nyuma yake, kama shingo nyembamba ya chupa.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Njia ya kuogelea (Swimlane)","text":"Mstari mlalo kwenye ubao unaokusanya kadi za aina moja, kama kazi za dharura au kadi za timu moja.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Njia ya kufanya kazi inayoondoa upotevu (kila kisichomsaidia mteja) na kuweka kazi ikitiririka."},{"id":"waste","g":"agile","word":"Upotevu (Waste)","text":"Katika Lean, kila kinachotumia juhudi lakini hakimsaidii mteja, kama kusubiri, kurudia kazi au kujenga vitu ambavyo hakuna anayevitumia.","noTip":1},{"id":"kaizen","g":"agile","word":"Uboreshaji endelevu","text":"Kuwa bora kidogo kidogo kila wakati kwa mabadiliko madogo ya kawaida, kisha kuangalia kama yalisaidia. Retro ni njia moja ya kufanya hivyo. Pia huitwa kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Timu inayojiongoza","text":"Timu inayoamua yenyewe jinsi ya kufanya kazi, badala ya kuambiwa hatua kwa hatua.","also":["timu inayojisimamia","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Timu yenye ujuzi mchanganyiko","text":"Timu yenye ujuzi wote inayouhitaji kukamilisha kazi yenyewe, kama usanifu, ujenzi na upimaji.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike (utafiti mfupi)","text":"Utafiti mfupi wenye kikomo cha muda wa kujibu swali kabla ya kujitolea kwenye kazi halisi.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Kurudia kazi","text":"Kufanya kazi tena kwa sababu haikuwa sahihi mara ya kwanza.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile ya ngazi kubwa (SAFe)","text":"Njia za kutumia Agile katika timu nyingi ndani ya shirika kubwa. SAFe (Scaled Agile Framework) ni mfano mmoja unaojulikana.","also":["scaled Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folda ya mradi ya msimbo pamoja na historia yake kamili ya commit. Inaweza kukaa kwenye kompyuta yako, kwenye GitHub, au zote mbili.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Mstari wa kazi uliotenganishwa kwenye msimbo, ili mabadiliko yafanywe bila kugusa toleo kuu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Nakala iliyohifadhiwa ya msimbo, pamoja na maelezo mafupi ya kilichobadilika. Unaweza kurudi kwenye moja wakati wowote.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Kutuma picha zako zilizohifadhiwa (commit) kutoka kompyuta hii hadi nakala ya pamoja mtandaoni, kama GitHub, ili zihifadhiwe akiba na wengine waweze kuzipata."},{"id":"merge","g":"build","word":"Merge","text":"Kuunganisha mabadiliko kutoka tawi moja hadi jingine, kwa kawaida kurudi kwenye toleo kuu."},{"id":"pr","g":"build","word":"Pull request","text":"Kuomba mabadiliko ya tawi yakaguliwe na kuunganishwa kwenye toleo kuu. Baadhi ya tovuti huliita merge request.","also":["PR","PRs","merge request","ombi la kuunganisha"]},{"id":"refactor","g":"build","word":"Refactor","text":"Kupanga msimbo bila kubadilisha unachofanya: faili ndogo zaidi, majina wazi zaidi, marudio machache."},{"id":"bug","g":"build","word":"Bug","text":"Kitu kisichofanya kazi kama kinavyopaswa.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Ukaguzi wa wenzako","text":"Jozi nyingine ya macho: mtu asiye mwandishi wa kazi huikagua kabla haijakufikia, ili makosa machache yapite. Kwenye AI-gile, AI nyingine hukagua kila kadi.","also":["peer review","ukaguzi wa msimbo","code review"]},{"id":"code","g":"build","word":"Msimbo (Code)","text":"Maagizo yaliyoandikwa yanayoiambia kompyuta cha kufanya. Pia huitwa msimbo chanzi (source code).","also":["msimbo","code","source code","msimbo chanzi"],"noTip":1},{"id":"proglang","g":"build","word":"Lugha ya programu","text":"Lugha ya kuandikia msimbo, kama JavaScript, Python au Java. Lugha tofauti zinafaa kazi tofauti.","also":["lugha za programu","programming language","programming languages"]},{"id":"developer","g":"build","word":"Msanidi programu (dev)","text":"Mtu anayeandika na kubadilisha msimbo. Pia huitwa mwanaprogramu au mhandisi wa programu.","also":["wasanidi programu","developer","developers","programmer","programmers","software engineer","mwanaprogramu"]},{"id":"software","g":"build","word":"Programu (Software)","text":"Programu zinazoendeshwa kwenye kompyuta na simu, tofauti na mashine zenyewe (hardware).","noTip":1},{"id":"app","g":"build","word":"Programu tumizi (App)","text":"Kifupi cha application: programu ambayo watu hutumia kufanya jambo, kwenye simu, kompyuta au kivinjari cha wavuti.","also":["app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Programu ya wavuti","text":"Programu inayoendeshwa kwenye kivinjari cha wavuti, kwa hiyo hakuna cha kusakinisha.","also":["programu za wavuti","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Upande wa mbele (Front end)","text":"Sehemu ya programu unayoiona na kubonyeza: skrini, vitufe na maneno, mara nyingi kwenye kivinjari chako.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Upande wa nyuma (Back end)","text":"Sehemu ya programu ya nyuma ya pazia inayohifadhi data na kufanya kazi unapobonyeza kitu, kama kukagua nenosiri lako.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Kufanya kazi pande zote mbili: upande wa mbele na upande wa nyuma.","also":["full-stack"]},{"id":"ui","g":"build","word":"Kiolesura cha mtumiaji (UI)","text":"Anachokiona na kutumia mtu kwenye skrini: mpangilio, vitufe, menyu na maandishi.","also":["UI","user interface","kiolesura"]},{"id":"ux","g":"build","word":"Uzoefu wa mtumiaji (UX)","text":"Jinsi inavyohisi kutumia kitu: rahisi, wazi na ya kupendeza, au ya kuchanganya na ya polepole.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Ufikivu (a11y)","text":"Kufanya vitu viweze kutumiwa na kila mtu, wakiwemo wasioona vizuri, wasioweza kutumia kipanya au wanaotumia kisomaji cha skrini.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Muundo unaojirekebisha (Responsive)","text":"Kufanya kurasa zitoshee na kufanya kazi vizuri kwenye ukubwa wowote wa skrini, kutoka simu hadi kifuatilizi kikubwa.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Mfumo wa usanifu (Design system)","text":"Seti ya pamoja ya rangi, fonti, vitufe na kanuni, ili kila skrini ionekane na kuenenda kwa njia ileile.","also":["design system","design systems"]},{"id":"architecture","g":"build","word":"Usanifu wa mfumo (Architecture)","text":"Umbo la jumla la mfumo: sehemu zake kuu ni zipi na jinsi zinavyowasiliana."},{"id":"database","g":"build","word":"Hifadhidata (Database)","text":"Hazina iliyopangwa ya taarifa, kama lahajedwali lenye nguvu sana ambalo programu inaweza kusoma na kubadilisha.","also":["database","databases","DB","hifadhidata"]},{"id":"schema","g":"build","word":"Muundo wa hifadhidata (Schema)","text":"Mpangilio wa hifadhidata: ina majedwali gani ya taarifa na kinachoingia kwenye kila moja.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kifupi cha structured query language: lugha inayotumika kuomba taarifa kutoka hifadhidata nyingi au kuzibadilisha.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Taarifa zinazohifadhiwa na kompyuta, kama majina, oda au mipangilio.","also":["takwimu","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Seva (Server)","text":"Kompyuta iliyowashwa kila wakati inayojibu maombi kutoka kompyuta nyingine, kama kutuma ukurasa wa wavuti unapoutembelea.","also":["seva","server","servers"]},{"id":"client","g":"build","word":"Mteja (Client)","text":"Upande unaoomba kitu, kwa kawaida kivinjari au programu yako, ukizungumza na seva. Kwenye biashara pia humaanisha mteja tu.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kifupi cha application programming interface: orodha ya maombi ambayo programu moja inaweza kuiomba nyingine, kama kuiomba huduma ya hali ya hewa utabiri wa leo.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (anwani ya huduma)","text":"Kipengele kimoja kwenye orodha ya API: anwani ya wavuti ambayo programu inaweza kuiita kupata au kutuma kitu.","also":["endpoint","endpoints"]},{"id":"integration","g":"build","word":"Kuunganisha mifumo (Integration)","text":"Kuunganisha mifumo miwili ili ifanye kazi pamoja, kama duka lako kutuma oda kwenye programu yako ya hesabu.","also":["integration","integrations","uunganishaji"]},{"id":"webhook","g":"build","word":"Webhook","text":"Ujumbe ambao mfumo mmoja hutuma kwa mwingine wenyewe wakati kitu kinapotokea, kama “malipo yamepokelewa”.","also":["webhooks"]},{"id":"library","g":"build","word":"Maktaba (Library)","text":"Msimbo uliotayarishwa na mtu mwingine ambao unaweza kuutumia tena badala ya kuuandika mwenyewe.","also":["maktaba","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Mfumo msingi (Framework)","text":"Muundo uliotayarishwa wa kujengea programu unaoamua sehemu kubwa ya mpangilio wa msimbo, kama fremu ya nyumba unayoijaza.","also":["framework","frameworks"]},{"id":"sdk","g":"build","word":"Seti ya zana za kuunda programu (SDK)","text":"Sanduku la zana, msimbo na mifano ya kujengea programu kwa jukwaa au huduma moja.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Utegemezi wa programu","text":"Maktaba au zana ambayo msimbo wako unaihitaji ili ufanye kazi. Kuziweka za kisasa ni muhimu kwa usalama.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Kifurushi (Package)","text":"Mkusanyiko wa msimbo uliotayarishwa unaoweza kuusakinisha na kuutumia kwenye mradi.","also":["kifurushi","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Kidhibiti vifurushi (Package manager)","text":"Zana inayopakua na kusasisha vifurushi ambavyo msimbo wako unavitegemea. npm ni mojawapo maarufu.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Zana inayotumika zaidi kuhifadhi historia ya mabadiliko ya msimbo, kwa njia ya commit na matawi (branch)."},{"id":"github","g":"build","word":"GitHub","text":"Tovuti inayohifadhi repo za Git mtandaoni, ili timu zishiriki msimbo, zikague mabadiliko na kufuatilia kazi."},{"id":"vcs","g":"build","word":"Udhibiti wa matoleo (Version control)","text":"Kuhifadhi historia kamili ya kila badiliko kwenye mafaili, ili uone nani alibadilisha nini na kurudi nyuma ikibidi. Git hufanya hivi.","also":["version control","source control","version control system","udhibiti wa matoleo"]},{"id":"clone","g":"build","word":"Kunakili repo (Clone)","text":"Kutengeneza nakala yako kamili ya repo, pamoja na historia yake, kwenye kompyuta yako.","also":["clone","cloned","cloning"]},{"id":"pull","g":"build","word":"Kuvuta (Pull)","text":"Kuleta commit za hivi karibuni kutoka kwenye nakala ya pamoja (kama GitHub) hadi kwenye kompyuta yako. Kinyume cha push.","also":["pull","git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Tawi kuu (Main branch)","text":"Toleo rasmi la msimbo ambalo kila mtu hulitumia kama msingi, mara nyingi huitwa main au master.","also":["main branch","master branch"]},{"id":"conflict","g":"build","word":"Mgongano wa kuunganisha (Merge conflict)","text":"Mabadiliko mawili yanapogusa mistari ileile kwa njia tofauti, kompyuta haiwezi kuyaunganisha na mtu lazima achague.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Tofauti (Diff)","text":"Mwonekano unaoonyesha hasa kilichobadilika kati ya matoleo mawili: mistari iliyoongezwa na mistari iliyoondolewa.","also":["diff","diffs"]},{"id":"fork","g":"build","word":"Fork (nakala yako ya repo)","text":"Nakala yako ya repo ya mtu mwingine, unayoweza kuibadilisha bila kuathiri yake.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"Hati ya kiotomatiki (Script)","text":"Programu fupi inayofanya kazi moja yenyewe, kama kupanga mafaili au kuanzisha programu.","also":["script","scripts"],"noTip":1},{"id":"build","g":"build","word":"Kujenga (Build)","text":"Kubadilisha msimbo kuwa kitu kilicho tayari kuendeshwa, au matokeo yenyewe yaliyo tayari kuendeshwa.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kukusanya msimbo (Compile)","text":"Kutafsiri msimbo walioandika watu kuwa umbo ambalo kompyuta inaweza kuliendesha moja kwa moja.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Mstari wa amri (CLI)","text":"Dirisha la maandishi ambapo unaandika maagizo kwa kompyuta badala ya kubonyeza. Pia huitwa terminal.","also":["mstari wa amri","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Usanidi (config)","text":"Mipangilio inayodhibiti jinsi programu inavyofanya kazi, iliyohifadhiwa mbali na msimbo ili iwe rahisi kubadilisha.","also":["usanidi","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Kigeuzi cha mazingira (Environment variable)","text":"Mpangilio unaopewa programu inapoanza, mara nyingi hutumika kwa anwani au nenosiri ili visiandikwe ndani ya msimbo.","also":["environment variable","environment variables","env var"]},{"id":"debugging","g":"build","word":"Kutatua hitilafu (Debugging)","text":"Kutafuta sababu ya kitu kutofanya kazi, na kukirekebisha.","also":["debugging","debug","debugged"]},{"id":"pairing","g":"build","word":"Kuandika msimbo kwa jozi (Pair programming)","text":"Watu wawili (au mtu na AI) wakifanya kazi pamoja kwenye msimbo uleule, mmoja akiandika na mwingine akikagua.","also":["pair programming","pairing"]},{"id":"docs","g":"build","word":"Nyaraka (docs)","text":"Maelezo yaliyoandikwa ya jinsi kitu kinavyofanya kazi au jinsi ya kukitumia.","also":["nyaraka","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Faili ya kwanza ya kusoma kwenye repo: mradi ni nini na jinsi ya kuufanya ufanye kazi.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Mfumo wa zamani (Legacy)","text":"Mfumo wa zamani ambao bado unatumika na ni mgumu kubadilisha, mara nyingi kwa sababu watu wachache bado wanauelewa.","also":["legacy system","legacy systems","legacy code","msimbo wa zamani"]},{"id":"techdebt","g":"build","word":"Deni la kiufundi (Technical debt)","text":"Njia za mkato zinazookoa muda sasa lakini zinafanya mabadiliko ya baadaye kuwa ya polepole, kama mkopo unaokusanya riba. Refactoring hulipa deni hilo.","also":["technical debt","tech debt"]},{"id":"test","g":"test","word":"Jaribio","text":"Ukaguzi kwamba kitu kinafanya kazi kama kinavyopaswa. Baadhi ya majaribio kompyuta huyaendesha yenyewe kila msimbo unapobadilika; mengine ni wewe ukijaribu kadi iliyokamilika kabla ya kuikubali.","also":["test","tests","majaribio","jaribu","kujaribu","uijaribu"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kifupi cha quality assurance (uhakikisho wa ubora): kila kinachofanywa kuhakikisha kazi ni sahihi kabla ya kwenda hewani. Kwenye AI-gile humaanisha ukaguzi wa kiotomatiki: QA ikiwa nyekundu, kuna kitu kimeshindwa, na haiwezi kwenda hewani hadi kirekebishwe.","also":["ukaguzi wa ubora","uhakikisho wa ubora"]},{"id":"testpile","g":"test","word":"Rundo la majaribio","text":"Kadi zilizokamilika zinazosubiri uzijaribu, moja baada ya nyingine. Kubali moja au irudishe pamoja na maelezo, na inayofuata itakuja.","also":["marundo ya majaribio"]},{"id":"autotest","g":"test","word":"Jaribio la kiotomatiki","text":"Ukaguzi ambao kompyuta huendesha yenyewe kila msimbo unapobadilika, ili kukamata makosa mapema.","also":["majaribio ya kiotomatiki","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Jaribio la mkono","text":"Mtu akijaribu kazi kwa mkono ili kuona kama inafanya kazi inavyopaswa.","also":["majaribio ya mkono","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Jaribio la kipande (Unit test)","text":"Ukaguzi mdogo wa kiotomatiki wa kipande kimoja kidogo cha msimbo peke yake.","also":["unit test","unit tests"]},{"id":"integtest","g":"test","word":"Jaribio la muunganiko (Integration test)","text":"Ukaguzi kwamba sehemu kadhaa zinafanya kazi vizuri pamoja, si moja moja tu.","also":["integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Jaribio la mwanzo hadi mwisho (E2E)","text":"Jaribio linaloiga mtumiaji halisi tangu mwanzo hadi mwisho, kama kujisajili, kununua na kulipa.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Majaribio ya kukubalika na mtumiaji (UAT)","text":"Watu walioomba kazi hiyo wanaijaribu wenyewe na kusema kama inafanya wanachohitaji. Rundo la majaribio la AI-gile ndilo toleo lake la hili.","also":["UAT","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"Kurudi nyuma (Regression)","text":"Kitu kilichokuwa kinafanya kazi lakini kikaharibika baada ya badiliko. Majaribio ya regression hukagua kwamba vitu vya zamani bado vinafanya kazi.","also":["regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Jaribio la haraka (Smoke test)","text":"Ukaguzi wa haraka sana kwamba mambo makuu yanafanya kazi kabisa, kwa mfano mara tu badiliko linapowekwa hewani. Ikishindwa, simama na uangalie.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Kupima kwa uchunguzi huru","text":"Kujaribu bidhaa kwa uhuru na kuichokoza kwa njia mbalimbali, kupata matatizo ambayo ukaguzi uliopangwa ungeyakosa.","also":["exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Kisa cha jaribio (Test case)","text":"Hali moja iliyoandikwa ya kujaribu: hatua, na kinachopaswa kutokea.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"Wigo wa majaribio (Test coverage)","text":"Kiasi cha msimbo kinachokaguliwa na majaribio ya kiotomatiki. Zaidi kwa kawaida ni salama zaidi, lakini wigo mkubwa pekee hauthibitishi kwamba msimbo unafanya kazi vizuri.","also":["test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Data ya majaribio","text":"Taarifa za mfano zilizobuniwa zinazotumika wakati wa kupima, ili taarifa binafsi za mtu halisi yeyote zisifichuliwe.","also":["test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Hali ya pembeni (Edge case)","text":"Hali isiyo ya kawaida kwenye mipaka, kama fomu tupu au jina lenye alama ya apostrofi, ambapo mambo mara nyingi huharibika.","also":["edge case","edge cases"]},{"id":"happypath","g":"test","word":"Njia ya furaha (Happy path)","text":"Njia ya kawaida ambapo kila kitu kinaenda sawa. Upimaji mzuri pia hujaribu njia zisizo za furaha."},{"id":"perftest","g":"test","word":"Kupima utendaji","text":"Kukagua kitu ni cha haraka kiasi gani na kinavyokabiliana na mzigo.","also":["performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Kupima mzigo","text":"Kukagua mfumo unavyokabiliana watu wengi wanapoutumia kwa wakati mmoja.","also":["load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Kupima usalama","text":"Kutafuta udhaifu unaoweza kumwezesha mtu kutumia mfumo vibaya au kuona asichostahili.","also":["security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Kupima ufikivu","text":"Kukagua kwamba watu wenye uwezo tofauti wanaweza kutumia bidhaa, ikiwemo kwa kisomaji cha skrini au kibodi pekee.","also":["accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting (ukaguzi wa mtindo)","text":"Ukaguzi wa kiotomatiki unaobaini makosa yanayowezekana na mtindo usio nadhifu kwenye msimbo, kama kikagua tahajia cha programu.","also":["linting","linter","lint"]},{"id":"static","g":"test","word":"Uchambuzi tuli (Static analysis)","text":"Kukagua msimbo kwa matatizo kwa kuusoma kiotomatiki, bila kuuendesha.","also":["static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Jaribio lisilotegemewa (Flaky test)","text":"Jaribio linalopita wakati mwingine na kushindwa wakati mwingine bila sababu wazi, kwa hiyo haliwezi kuaminika kikamilifu.","also":["flaky test","flaky tests"]},{"id":"repro","g":"test","word":"Kurudisha tatizo (Reproduce)","text":"Kufanya hitilafu itokee tena kwa makusudi kwa kufuata hatua zilezile, ili ichunguzwe na kurekebishwa. Kuandika hatua hizo ndio sehemu yenye manufaa zaidi ya ripoti ya hitilafu.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Ukali wa tatizo (Severity)","text":"Jinsi athari ya tatizo ilivyo mbaya, kuanzia kero ndogo hadi kila kitu kusimama.","also":["severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kunakili toleo jipya la programu kwenye kompyuta zinazoiendesha, kama nakala ya majaribio au huduma ya hewani."},{"id":"release","g":"change","word":"Toleo","text":"Kifurushi chenye jina cha kazi iliyokamilika kinachoenda hewani pamoja, na maelezo mafupi ya kilichobadilika. 🚀 Matoleo huandika maelezo kutoka kwenye kadi zilizokamilika.","also":["matoleo","release"]},{"id":"rollback","g":"change","word":"Rudisha nyuma","text":"Kurudi kwenye toleo la mwisho lililofanya kazi pale jipya linaposababisha shida. Kwenye AI-gile, Roll back hukusanya hatua za kutengua zilizoandikwa kwenye kila badiliko kuwa orodha moja ya ukaguzi.","also":["rollback","kurudisha nyuma","imerudishwa nyuma"]},{"id":"live","g":"change","word":"Hewani","text":"Toleo halisi ambalo watu wanatumia, tofauti na nakala ya kujaribia mambo. Wasanidi programu pia huliita production.","also":["live","production","uzalishaji"],"noTip":1},{"id":"change","g":"change","word":"Badiliko","text":"Badiliko lililopangwa kwa kitu ambacho watu wanakitegemea, likiandikwa kwanza: nini, kwa nini, hatari, lini, na jinsi ya kulitendua. Lianzishe kwa 🔀 Omba badiliko.","also":["mabadiliko","ombi la badiliko","maombi ya mabadiliko"],"noTip":1},{"id":"risk","g":"change","word":"Hatari","text":"Kitu kinachoweza kwenda vibaya, kilichopewa alama kulingana na uwezekano wake na ubaya wake. ⚠️ Hatari huziweka kwenye orodha moja, alama ya juu kwanza, kila moja ikiwa na tarehe ya kuiangalia tena.","also":["hatari nyingi","rejista ya hatari"]},{"id":"chgwin","g":"change","word":"Dirisha la mabadiliko","text":"Nyakati ambazo mabadiliko yanaruhusiwa kwenda hewani, kama jioni tulivu ya Jumanne. Nje ya dirisha kadi ya badiliko haiwezi kukamilishwa, isipokuwa ni dharura.","also":["madirisha ya mabadiliko","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Ukaguzi wa mwisho kabla badiliko halijaenda hewani: kila mtu anayepaswa kuidhinisha anasema Go au No go. Linaendelea tu pale kila mtu anaposema Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Idhini","text":"Kusubiri ndiyo kabla kazi haijaanza. Kadi aliyoiomba rafiki, au badiliko, husubiri katika ✅ Idhini mpaka uikubali au uikatae.","also":["idhini nyingi","kuidhinisha"]},{"id":"quiettime","g":"change","word":"Wakati wa utulivu","text":"Kipindi, kama wakati wa matangazo ya moja kwa moja, onyesho au usiku kucha, ambapo hakuna kinachoenda hewani. Timu zinaendelea kufanya kazi na kupima, lakini kwenda hewani kunasubiri hadi kiishe. Sehemu nyingine huitwa kusimamisha mabadiliko (change freeze).","also":["nyakati za utulivu","kusimamisha mabadiliko","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Njia ya kufanya kazi ambapo wanaojenga programu na wanaoiendesha hufanya kazi kama timu moja, kwa otomatiki nyingi, ili mabadiliko yaende hewani mara kwa mara na kwa usalama."},{"id":"cicd","g":"change","word":"CI/CD (uunganishaji na utoaji endelevu)","text":"Mabadiliko ya kila mtu huunganishwa kwenye toleo kuu mara kwa mara na kukaguliwa kiotomatiki kila mara (continuous integration), ili programu iwe tayari kila wakati kwenda hewani kwa kubonyeza kitufe (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Usambazaji endelevu (Continuous deployment)","text":"Hatua moja zaidi ya continuous delivery: kila badiliko linalopita ukaguzi huenda hewani lenyewe, bila kitufe cha kubonyeza.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Bomba la kazi (Pipeline)","text":"Mfululizo wa kiotomatiki wa hatua ambazo badiliko hupitia njiani kuelekea hewani, kama kujenga, kupima, kisha kusambaza.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Mazingira (Environment)","text":"Nakala moja tofauti ya mfumo kwa kusudi moja, kama ya kujengea, ya kupimia na ya hewani.","also":["environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Mazingira ya uundaji","text":"Nakala anayofanyia kazi msanidi, mara nyingi kwenye kompyuta yake mwenyewe, ambapo kuharibu vitu hakumdhuru mtu.","also":["development environment","dev environment"]},{"id":"testenv","g":"change","word":"Mazingira ya majaribio","text":"Nakala tofauti ya mfumo inayotumika kupimia tu, ili huduma halisi isiguswe.","also":["test environment","test environments"]},{"id":"staging","g":"change","word":"Mazingira ya maandalizi (Staging)","text":"Nakala ya mwisho iliyoundwa kama ya hewani, kwa ukaguzi wa mwisho kabla badiliko halijaenda hewani.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Matokeo ya ujenzi (Build artifact)","text":"Faili au kifurushi ambacho ujenzi huzalisha, tayari kuhifadhiwa, kukaguliwa au kuwekwa hewani.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Marekebisho ya dharura (Hotfix)","text":"Marekebisho ya haraka yanayowekwa hewani kwa kasi, nje ya mpango wa kawaida, kwa sababu kitu muhimu kimeharibika.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Kiraka (Patch)","text":"Sasisho dogo linalorekebisha hitilafu au kuziba pengo la usalama. Kuweka viraka vya usalama haraka ni muhimu.","also":["kiraka","patch","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Namba ya toleo","text":"Lebo kama 2.4.1 inayosema una toleo lipi. Mara nyingi namba ya kwanza hubadilika kwa mabadiliko makubwa na ya mwisho kwa marekebisho madogo.","also":["namba za toleo","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Maelezo ya toleo (Release notes)","text":"Orodha fupi na rahisi ya kilichobadilika katika toleo, kwa watu wanaolitumia, ikiwemo marekebisho na mipaka inayojulikana. Pia huitwa changelog.","also":["release notes","changelog","change log"]},{"id":"flag","g":"change","word":"Swichi ya kipengele (Feature flag)","text":"Swichi ya kuwasha na kuzima kipengele, ili kazi mpya iende hewani ikiwa imefichwa na kuwashwa (au kuzimwa tena) bila toleo jipya.","also":["feature flag","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Kusonga mbele (Roll forward)","text":"Kurekebisha toleo baya kwa kutoa haraka toleo jipya lililosahihishwa badala ya kurudi kwenye la zamani.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Toleo la majaribio kwa wachache (Canary)","text":"Kuweka badiliko hewani kwa kikundi kidogo kwanza, na kwa kila mtu baada tu ya kuonekana kuwa sawa. Limepewa jina la ndege kanari ambao wachimba migodi waliwachukua chini ardhini kama onyo la mapema.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Usambazaji wa buluu-kijani (Blue-green)","text":"Kuweka nakala mbili za mfumo wa hewani na kuwahamishia watu kwenye mpya kwa mara moja, ili urudi mara moja ikienda vibaya.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Usambazaji bila kusimama","text":"Kuweka toleo jipya hewani bila huduma kusimama kamwe kwa watumiaji wake.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Kuwezesha mabadiliko (Change enablement)","text":"Kusaidia mabadiliko yafanikiwe: kupima hatari, kupata idhini sahihi na kuchagua wakati mzuri. Pia huitwa usimamizi wa mabadiliko (change management).","also":["change enablement","change management","usimamizi wa mabadiliko"]},{"id":"cab","g":"change","word":"Bodi ya ushauri wa mabadiliko (CAB)","text":"Kikundi kinachopitia mabadiliko muhimu na kukubaliana kama yaendelee na lini.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Badiliko lililoidhinishwa awali (Standard change)","text":"Badiliko lenye hatari ndogo linalofanywa kwa njia ileile iliyojaribiwa kila mara, kwa hiyo huidhinishwa mapema.","also":["standard change","standard changes"]},{"id":"normchange","g":"change","word":"Badiliko la kawaida (Normal change)","text":"Badiliko linalohitaji kukaguliwa na kuidhinishwa kabla halijaendelea.","also":["normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Badiliko la dharura (Emergency change)","text":"Badiliko linalopaswa kufanyika mara moja kurekebisha au kuzuia shida kubwa, kwa idhini ya haraka zaidi inayolingana.","also":["emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Otomatiki (Automation)","text":"Kuifanya kompyuta ifanye kazi inayojirudia yenyewe, ili iwe ya haraka na ifanywe kwa njia ileile kila mara.","also":["otomatiki","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Miundombinu (Infrastructure)","text":"Mashine, mitandao na huduma ambazo programu huendeshwa juu yake.","also":["miundombinu","infrastructure","infra"]},{"id":"iac","g":"change","word":"Miundombinu kama msimbo (IaC)","text":"Kueleza seva na mipangilio yako kwenye mafaili yanayohifadhiwa pamoja na msimbo, ili ijengwe upya kwa njia ileile kamili kila mara.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Wingu (Cloud)","text":"Kukodisha kompyuta, hifadhi na huduma kutoka kwa mtoa huduma mkubwa kupitia intaneti, badala ya kumiliki mashine mwenyewe.","also":["wingu","cloud","the cloud","cloud computing","kompyuta ya wingu"]},{"id":"provider","g":"change","word":"Mtoa huduma za wingu","text":"Kampuni inayokodisha huduma za kompyuta kupitia intaneti, kama Amazon Web Services (AWS), Microsoft Azure au Google Cloud.","also":["watoa huduma za wingu","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Uhifadhi wa tovuti (Hosting)","text":"Mahali programu au tovuti yako inapoishi na kufanya kazi ili watu waifikie, kwa kawaida hukodishwa kutoka kampuni.","also":["hosting","kuhifadhi tovuti"]},{"id":"domain","g":"change","word":"Jina la kikoa (Domain)","text":"Anwani ya wavuti ambayo watu huandika, kama example.com. Unaikodisha kwa mwaka, kwa hiyo lazima uihuishe.","also":["kikoa","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Kifupi cha domain name system: kitabu cha anwani cha intaneti, kinachogeuza jina kama example.com kuwa anwani ya kompyuta sahihi.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontena (Container)","text":"Kifurushi kilichofungwa chenye programu na kila inachohitaji, ili ifanye kazi vilevile kwenye kompyuta yoyote. Docker ndiyo zana maarufu zaidi.","also":["kontena","container","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Kompyuta pepe (VM)","text":"Kompyuta bandia inayoendeshwa ndani ya kompyuta halisi, ili mashine moja kubwa ifanye kazi kama nyingi.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (bila kusimamia seva)","text":"Kuendesha msimbo bila kutunza seva zozote mwenyewe: mtoa huduma huuendesha unapohitajika na unalipia unachotumia tu."},{"id":"lb","g":"change","word":"Kisawazishaji mzigo (Load balancer)","text":"Kitu kinachosambaza wageni kwenye seva kadhaa, ili hakuna seva moja inayozidiwa.","also":["load balancer","load balancers"]},{"id":"cache","g":"change","word":"Kashe (Cache)","text":"Hifadhi ya karibu ya matokeo ya hivi karibuni, ili jambo lilelile lisilazimike kuletwa au kukokotolewa tena. Kuifuta kunaweza kurekebisha kurasa zinazoonekana za zamani.","also":["kashe","cache","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Mtandao wa kusambaza maudhui (CDN)","text":"Seti ya seva duniani kote zenye nakala za kurasa na picha zako karibu na wageni wako, ili zipakie haraka.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Uhamishaji (Migration)","text":"Kuhamisha data au mifumo kutoka mpangilio wa zamani hadi mpya, au kubadilisha kwa uangalifu jinsi hifadhidata ilivyopangwa.","also":["uhamishaji","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Huduma","text":"Kitu ulichojenga ambacho watu wanakitegemea, kama tovuti au programu, kinachotunzwa ili kiendelee kufanya kazi. Weka alama kwenye “Mradi huu ni huduma” na useme kinatoa nini, nani anakitumia na nani yuko zamu.","also":["huduma nyingi","service"]},{"id":"uptimepct","g":"run","word":"Muda wa kufanya kazi (Uptime)","text":"Sehemu ya muda ambayo huduma inafanya kazi, kwa kawaida kama asilimia. 99.9% bado inaruhusu takriban dakika 43 za kuzimika kwa mwezi.","also":["uptime","uptime percentage"]},{"id":"uptime","g":"run","word":"Ukaguzi wa upatikanaji","text":"Ukaguzi wa kiotomatiki, kila baada ya dakika chache, kwamba huduma yako bado inajibu. Ukishindwa mara kadhaa mfululizo, AI-gile hufungua kadi ya tukio yenyewe.","also":["uptime checks","ukaguzi wa uptime"]},{"id":"statuspage","g":"run","word":"Ukurasa wa hali","text":"Ukurasa wa umma unaoonyesha kama huduma inafanya kazi (kijani, machungwa au nyekundu) pamoja na habari ya karibuni, ili wanaoitumia waweze kuangalia badala ya kuuliza.","also":["kurasa za hali","status page"]},{"id":"desk","g":"run","word":"Dawati la huduma","text":"Mahali ambapo maswali na ripoti kutoka kwa watu wanaotumia huduma yako hufika. AI-gile hupanga kila moja kama ombi, tukio au wazo, na husema ikiwa inaonekana kama kitu kilichokwisha ripotiwa.","also":["madawati ya huduma","dawati","dawati la msaada","helpdesk"]},{"id":"svcrequest","g":"run","word":"Ombi la huduma","text":"Mtu anapoomba kitu cha kawaida, kama akaunti mpya au msaada kidogo, badala ya kuripoti kwamba kitu kimeharibika. Husubiri zamu yake; tukio huja kwanza.","also":["maombi ya huduma","ombi","maombi"]},{"id":"incident","g":"run","word":"Tukio","text":"Kitu kilichoharibika au kisichofanya kazi ipasavyo kwa watu wanaokitumia sasa hivi, kama tovuti kuzimika au kuwa polepole sana. Kadi ya tukio ya 🔥 inaruka foleni: kuirudisha huduma ifanye kazi kunatangulia yote.","also":["matukio","incident"]},{"id":"major","g":"run","word":"Tukio kubwa","text":"Tukio kubwa: watu wengi wameathirika, au pesa au data ziko hatarini. Kitufe kimoja huweka kila timu juu yake (kundi), humwamsha aliye zamu na huomba habari ya hali kila dakika 30.","also":["matukio makubwa","major incident"]},{"id":"oncall","g":"run","word":"Zamu","text":"Kuwa yule anayejibu kitu kinapoharibika, hata usiku. Kila huduma ina mwanatimu wa zamu anayeamshwa kwanza kwa matukio yake.","also":["aliye zamu","on call","on-call"]},{"id":"replyby","g":"run","word":"Muda wa kujibu","text":"Kadi inaweza kusubiri jibu la kwanza kwa muda gani, kwa mfano saa moja kwa tukio. Baada ya hapo inapata saa nyekundu, ili hakuna kinachosahaulika kimya kimya. Pia huitwa lengo la kujibu.","also":["nyakati za kujibu","lengo la kujibu"]},{"id":"postmortem","g":"run","word":"Uchambuzi wa baada ya tukio","text":"Kuangalia nyuma kwa ufupi baada ya tukio: nini kilitokea, nini kilisaidia na nini cha kubadilisha, bila kumlaumu mtu yeyote. Tukio haliwezi kufungwa bila uchambuzi huu. Mara nyingi huitwa post-mortem.","also":["post-mortem","postmortem","uchambuzi wa tukio"]},{"id":"problem","g":"run","word":"Tatizo","text":"Chanzo kilichojificha nyuma ya tukio moja au zaidi. Kadi ya 🧩 tatizo hukusanya matukio yanayojirudia, ili chanzo kipatikane na kirekebishwe kabisa.","also":["matatizo","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Chanzo kikuu","text":"Sababu halisi kitu kilivyoharibika, si tu kile ulichoona kikienda vibaya. Rekebisha chanzo kikuu na tukio litaacha kujirudia.","also":["vyanzo vikuu","root cause"]},{"id":"workaround","g":"run","word":"Suluhisho la muda","text":"Njia ya kufanya mambo yaendelee mpaka suluhisho halisi liwe tayari, kama kuwasha upya kitu kinapokwama. Huandikwa kwenye kadi ya tatizo ili mtu yeyote asilazimike kulitafuta tena.","also":["masuluhisho ya muda","workaround"]},{"id":"knownerror","g":"run","word":"Kosa linalojulikana","text":"Tatizo ambalo chanzo chake kinaeleweka lakini bado halijarekebishwa, kwa kawaida likiwa na njia mbadala iliyoandikwa. 🧩 Makosa yanayojulikana huyaorodhesha, ili kila mtu atumie njia mbadala badala ya kuchimba tena.","also":["makosa yanayojulikana","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Maelekezo ya hatua kwa hatua ya kurekebisha aina ya tatizo linalojulikana, ili lifanyike kwa njia ileile, haraka, kila mara. Baada ya tukio kubwa timu inaweza kupendekeza moja uikubali.","also":["runbooks","mwongozo wa hatua"]},{"id":"ci","g":"run","word":"Kipengee cha usanidi","text":"Kitu kimoja ambacho huduma yako inakitegemea, kama seva, kikoa, cheti, ufunguo au msambazaji. 🗂️ Vipengee vya usanidi huviorodhesha kwa kila huduma, ili uone tukio linaathiri nini na nini kinahitaji kufanywa upya au kuhifadhiwa nakala.","also":["vipengee vya usanidi"]},{"id":"expiry","g":"run","word":"Tarehe ya kuisha muda","text":"Tarehe ambayo kitu huacha kufanya kazi kisipohuishwa, kama cheti cha usalama cha tovuti au anwani yake ya wavuti. AI-gile hufuatilia tarehe hizi na hutengeneza kadi moja ya kuhuisha kila kimoja siku 30 kabla, ili kisisimame chochote ghafla.","also":["tarehe za kuisha muda","kuisha muda","ufuatiliaji wa muda wa kuisha"]},{"id":"backup","g":"run","word":"Nakala rudufu","text":"Nakala iliyohifadhiwa ya data yako ya awali, ya kutegemea kitu kikipotea au kuharibika. AI-gile hutengeneza nakala rudufu ya mbao zako kila siku.","also":["nakala rudufu nyingi","backup","hifadhi nakala"]},{"id":"restore","g":"run","word":"Rejesha","text":"Kurudisha data kutoka kwenye nakala rudufu. Nakala rudufu ina thamani kweli pale tu unapojua inaweza kurejeshwa, kwa hiyo inafaa kujaribu mara kwa mara.","also":["kurejesha","imerejeshwa","restore"]},{"id":"svcreview","g":"run","word":"Mapitio ya huduma","text":"Kutazama nyuma mwezi mmoja wa huduma: matukio yaliyofunguliwa na kurekebishwa, jinsi watu walivyopata jibu haraka, upatikanaji na tokeni zilizotumika. Mapitio ya kila mwezi huonyesha hili kwa kila huduma.","also":["mapitio ya kila mwezi","mapitio ya mwezi"]},{"id":"accessreview","g":"run","word":"Mapitio ya ufikiaji","text":"Kukagua kila siku 90 nani bado anaweza kuingia: viungo vya kushiriki, majukumu ya marafiki na manenosiri na funguo zilizohifadhiwa. Unabakiza au kuondoa kila kimoja, ili ufikiaji wa zamani usibaki.","also":["mapitio ya ruhusa"]},{"id":"improvements","g":"run","word":"Orodha ya maboresho","text":"Kila kitu ambacho timu iliamua kukifanya vizuri zaidi, mahali pamoja: mapendekezo ya retro, hatua za mapitio na marekebisho ya matatizo, kila kimoja na hali yake. Kipate chini ya 📈 Maboresho.","also":["orodha za maboresho","maboresho"]},{"id":"tokencap","g":"run","word":"Kikomo cha tokeni","text":"Kikomo cha kila mwezi cha tokeni ambazo mawakala wa huduma wanaweza kutumia. Ukifika 80% unapata onyo; ukifika 100% kazi zao za chinichini husubiri hadi mwezi ujao au hadi uongeze kikomo.","also":["vikomo vya tokeni"]},{"id":"svcmgmt","g":"run","word":"Usimamizi wa huduma","text":"Kila kinachohusika kuweka huduma yenye manufaa na inayofanya kazi kwa watu wanaoitegemea, siku baada ya siku.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Mwongozo unaotumika sana wa usimamizi mzuri wa huduma, unaoshughulikia mambo kama matukio, matatizo na mabadiliko. Zamani jina hilo lilimaanisha IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Usimamizi wa huduma za TEHAMA (ITSM)","text":"Kuendesha teknolojia kama huduma kwa watu, kwa njia wazi za kushughulikia maombi, matukio, mabadiliko na maboresho.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Huduma inayosimamiwa (Managed service)","text":"Huduma ambayo mtu mwingine anaiendesha na kuitunza kwa ajili yako, chini ya makubaliano ya jinsi inavyopaswa kufanya kazi vizuri.","also":["managed service","managed services"]},{"id":"svcowner","g":"run","word":"Mmiliki wa huduma","text":"Mtu anayewajibika kwa huduma nzima: inavyofanya kazi vizuri, inagharimu nini na inavyoboreshwa.","also":["wamiliki wa huduma","service owner","service owners"]},{"id":"sla","g":"run","word":"Makubaliano ya kiwango cha huduma (SLA)","text":"Ahadi iliyoandikwa kwa wateja kuhusu jinsi huduma itakavyofanya kazi vizuri, kama “inafanya kazi 99.9% ya muda” au “kujibiwa ndani ya saa moja”, mara nyingi pamoja na kurudishiwa pesa ikivunjwa.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Lengo la kiwango cha huduma (SLO)","text":"Lengo la timu yenyewe la jinsi huduma inavyopaswa kufanya kazi vizuri kwa kipindi, kwa kawaida likiwekwa kali kidogo kuliko SLA ili kuwa salama.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Kiashiria cha kiwango cha huduma (SLI)","text":"Kipimo halisi unachokagua dhidi ya lengo, kama sehemu ya ziara zilizopakia vizuri.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Upatikanaji (Availability)","text":"Kama watu wanaweza kutumia huduma wanapoihitaji, mara nyingi hupimwa kama uptime.","also":["upatikanaji","availability","high availability"]},{"id":"downtime","g":"run","word":"Muda wa kuzimika (Downtime)","text":"Muda ambao huduma haifanyi kazi au imezimwa, uliopangwa au la.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Bajeti ya makosa (Error budget)","text":"Kiasi kidogo cha kushindwa ambacho lengo lako la kuaminika linaruhusu. Kikiwepo bado unaweza kuchukua hatari na mabadiliko; kikiisha, unapunguza kasi.","also":["error budget","error budgets"]},{"id":"outage","g":"run","word":"Kukatika kwa huduma (Outage)","text":"Wakati huduma imezimika au imeharibika vibaya kwa watumiaji wake.","also":["outage","outages"]},{"id":"degraded","g":"run","word":"Huduma dhaifu (Degraded)","text":"Inafanya kazi, lakini vibaya: polepole, au baadhi ya sehemu hazifanyi kazi.","also":["degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Ufuatiliaji (Monitoring)","text":"Kuitazama huduma kiotomatiki wakati wote, ili matatizo yagunduliwe, ikiwezekana kabla watumiaji hawajaona.","also":["ufuatiliaji","monitoring"]},{"id":"observability","g":"run","word":"Uwezo wa kuona ndani (Observability)","text":"Jinsi unavyoweza kujua kinachoendelea ndani ya mfumo ukiwa nje, kwa kutumia kumbukumbu zake, namba na ufuatiliaji wa njia.","also":["observability","o11y"]},{"id":"log","g":"run","word":"Kumbukumbu (Log)","text":"Shajara inayoendelea ambayo programu huweka ya inachofanya, inayotumika kubaini nini kilienda vibaya.","also":["log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Ufuatiliaji wa njia (Trace)","text":"Rekodi ya jinsi ombi moja linavyosafiri kupitia sehemu mbalimbali za mfumo, hatua kwa hatua, inayoonyesha mahali lilipochelewa.","also":["trace","traces","tracing"]},{"id":"latency","g":"run","word":"Ucheleweshaji (Latency)","text":"Muda ambao kitu kinachukua kujibu, kama kusubiri kati ya kubonyeza na ukurasa kutokea.","also":["latency"]},{"id":"alert","g":"run","word":"Tahadhari (Alert)","text":"Ujumbe wa kiotomatiki kwamba kitu kinahitaji umakini, kama tovuti kutojibu.","also":["tahadhari","alert","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Uchovu wa tahadhari","text":"Pale tahadhari ni nyingi mno hadi watu wanaanza kuzipuuza, zikiwemo muhimu.","also":["alert fatigue","alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashibodi","text":"Skrini inayoonyesha namba na hali muhimu zaidi kwa mtazamo mmoja.","also":["dashboard","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Kupigiwa simu ya dharura (Paging)","text":"Kumpigia simu kwa haraka au kumwamsha mtu aliye zamu kuhusu tatizo.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Kupandisha ngazi (Escalation)","text":"Kumleta mtu mwenye ujuzi au mamlaka zaidi pale suala haliwezi kutatuliwa katika ngazi ya sasa, au haraka vya kutosha.","also":["escalation","escalate","escalated"]},{"id":"triage","g":"run","word":"Kupanga kwa udharura (Triage)","text":"Kupanga haraka masuala yanayoingia kwa jinsi yalivyo ya dharura na muhimu, ili mabaya zaidi yashughulikiwe kwanza.","also":["triage","triaged"]},{"id":"impact","g":"run","word":"Athari (Impact)","text":"Kiasi ambacho kitu kinawaathiri watu: wangapi, na kwa ubaya kiasi gani.","noTip":1},{"id":"urgency","g":"run","word":"Uharaka (Urgency)","text":"Kitu kinahitaji kushughulikiwa kwa haraka kiasi gani. Athari na uharaka pamoja huweka kipaumbele.","noTip":1},{"id":"plevels","g":"run","word":"Viwango vya kipaumbele (P1, P2…)","text":"Lebo za jinsi suala lilivyo la dharura. P1 ndilo zito zaidi na linahitaji hatua mara moja.","also":["P1","P2","P3","P4","priority levels"]},{"id":"queue","g":"run","word":"Foleni ya tiketi","text":"Orodha ya maombi na matukio yanayosubiri kuchukuliwa.","also":["foleni za tiketi","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Ngazi ya kwanza na ya pili","text":"Ngazi za msaada: ngazi ya kwanza hupokea simu na kurekebisha mambo rahisi; ya pili ina ujuzi wa kina kwa magumu zaidi. Pia huitwa tier 1 na tier 2.","also":["first-line support","tier 1","tier 2","msaada wa ngazi ya kwanza"]},{"id":"ic","g":"run","word":"Kamanda wa tukio (Incident commander)","text":"Mtu mmoja anayeongoza hatua dhidi ya tukio, ili kila mtu ajue nani anaamua na nani anafanya nini.","also":["incident commander","incident commanders","makamanda wa tukio"]},{"id":"responsetime","g":"run","word":"Muda wa kujibu","text":"Muda unaopita kabla mtu hajalichukua ombi au tukio kwa mara ya kwanza.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Muda wa kutatua","text":"Inachukua muda gani kulitatua kikamilifu ombi au tukio, tangu liripotiwe hadi lirekebishwe.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Wastani wa muda wa kurejesha (MTTR)","text":"Kwa wastani, huduma inachukua muda gani kufanya kazi tena baada ya kuharibika. MTTR inaweza kumaanisha mambo yanayotofautiana kidogo, kwa hiyo sema unachopima.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Wastani wa muda kati ya hitilafu (MTBF)","text":"Kwa wastani, huduma inafanya kazi kwa muda gani kabla kitu hakijaharibika.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Hifadhidata ya usimamizi wa usanidi (CMDB)","text":"Orodha ya vipengele vyako vyote vya usanidi na jinsi vinavyounganishwa, ili uone nini kinategemea nini.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Mali (Asset)","text":"Chochote chenye thamani unachomiliki au kulipia ili kuendesha huduma, kama kompyuta mpakato, leseni ya programu au kikoa.","also":["asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Kupanga uwezo (Capacity planning)","text":"Kuhakikisha kutakuwa na nguvu ya kutosha ya kompyuta, hifadhi na watu kwa yanayokuja.","also":["capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Kupanua uwezo (Scaling)","text":"Kukabiliana na watumiaji zaidi kwa kuipa mashine nguvu zaidi (scaling up) au kuongeza mashine zaidi (scaling out).","also":["scaling","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Mwendelezo wa biashara","text":"Mipango ya kuendeleza mambo muhimu pale kitu kikubwa kinapoharibika, kama kupoteza ofisi, mtoa huduma muhimu au kompyuta.","also":["business continuity","business continuity plan","mpango wa mwendelezo wa biashara"]},{"id":"dr","g":"run","word":"Kurejesha baada ya maafa (DR)","text":"Mpango na zana za kurudisha huduma baada ya jambo zito, kama kupoteza kituo kizima cha data.","also":["DR","disaster recovery"]},{"id":"rto","g":"run","word":"Lengo la muda wa kurejesha (RTO)","text":"Muda mrefu zaidi huduma inaweza kuwa imezimika baada ya maafa kabla ya kulazimika kufanya kazi tena.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Lengo la kiwango cha data kurejeshwa (RPO)","text":"Kiasi cha data ya hivi karibuni unachoweza kukubali kupoteza, kinachopimwa kwa muda. RPO ya saa moja inamaanisha nakala za akiba angalau kila saa.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Akiba ya ziada (Redundancy)","text":"Kuwa na vipuri tayari, kama seva ya pili, ili hitilafu moja isisimamishe huduma.","also":["redundancy"]},{"id":"failover","g":"run","word":"Kuhamia akiba (Failover)","text":"Kuhamia mfumo wa akiba wenyewe pale ule wa kawaida unapoharibika.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Kiungo kimoja cha kuangusha mfumo (Single point of failure)","text":"Sehemu moja inayoangusha kila kitu inapoharibika, kwa sababu hakuna akiba.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Dirisha la matengenezo","text":"Wakati uliopangwa ambapo huduma inaweza kusitishwa au kuwa polepole kwa matengenezo, unaotangazwa kwa watumiaji mapema.","also":["maintenance window","maintenance windows","planned maintenance","matengenezo yaliyopangwa"]},{"id":"handover","g":"run","word":"Makabidhiano","text":"Kumkabidhi mtu au timu nyingine kazi, maarifa na uwajibikaji, ili kisipotee chochote.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Hazina ya maarifa","text":"Mkusanyiko wa makala za msaada na majibu, kwa watumiaji na kwa timu.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Kuridhika kwa mteja (CSAT)","text":"Alama kutoka kwa watumiaji zinazosema walifurahi kiasi gani, mara nyingi huulizwa baada ya ombi kufungwa.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Msambazaji","text":"Kampuni ya nje unayoitegemea, kama mtoa huduma wako wa hosting. Pia huitwa muuzaji (vendor) au mhusika wa tatu (third party).","also":["wasambazaji","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Kustaafisha huduma","text":"Kuzima huduma kabisa kwa usalama: kuwaambia watumiaji wake, kushughulikia data na ufikiaji wake, na kusimamisha gharama zake.","also":["service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Mwisho wa maisha ya bidhaa (EOL)","text":"Bidhaa inapoacha kupata masasisho au msaada kutoka kwa mtengenezaji wake, kwa hiyo inapaswa kubadilishwa.","also":["EOL","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Usalama wa mtandao (Cybersecurity)","text":"Kulinda mifumo na data isivamiwe, kuibwa au kuharibiwa.","also":["usalama wa mtandao","cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Uthibitishaji wa utambulisho (Authentication)","text":"Kuhakiki mtu ni nani, kwa kawaida kwa nenosiri au msimbo. Mara nyingi hufupishwa authn.","also":["uthibitishaji","authentication","authn"]},{"id":"authz","g":"sec","word":"Utoaji wa ruhusa (Authorisation)","text":"Kuhakiki mtu anaruhusiwa kufanya nini baada ya kujua yeye ni nani. Mara nyingi hufupishwa authz.","also":["authorisation","authorization","authz"]},{"id":"mfa","g":"sec","word":"Uthibitishaji wa hatua nyingi (MFA)","text":"Kuingia kwa vithibitisho viwili au zaidi, kama nenosiri pamoja na msimbo kwenye simu yako. Pia huitwa two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"Kuingia mara moja (SSO)","text":"Kuingia mara moja ili kufikia mifumo mingi, kama kutumia akaunti yako ya kazi kila mahali.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Kidhibiti nenosiri","text":"Programu inayotengeneza manenosiri imara na kuyakumbuka kwa ajili yako.","also":["vidhibiti nenosiri","password manager","password managers"]},{"id":"secret","g":"sec","word":"Siri (Secret)","text":"Nenosiri, ufunguo au msimbo mwingine wa faragha ambao programu hutumia kuingia mahali. Haipaswi kushirikiwa wala kuandikwa ndani ya msimbo kamwe.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Ufunguo wa API","text":"Msimbo wa siri unaoruhusu programu kutumia API ya huduma nyingine, na kuonyesha nani anaitumia (na kuilipia).","also":["funguo za API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Tokeni ya ufikiaji (Access token)","text":"Pasi ya muda inayothibitisha programu inaruhusiwa kuingia, ili isihitaji nenosiri lako kila mara. Si sawa na tokeni ya AI.","also":["access token","access tokens"]},{"id":"encryption","g":"sec","word":"Usimbaji fiche (Encryption)","text":"Kuchanganya taarifa ili mtu mwenye ufunguo sahihi tu aweze kuzisoma.","also":["usimbaji fiche","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Njia salama ambayo kurasa za wavuti husafiri, inayoonyeshwa na kufuli kwenye kivinjari chako, ili asiwepo mtu katikati anayeweza kuzisoma au kuzibadilisha."},{"id":"cert","g":"sec","word":"Cheti cha SSL/TLS","text":"Kitambulisho cha kidijitali kinachoruhusu tovuti kuthibitisha ni nani na kutumia HTTPS. Huisha muda, kwa hiyo lazima kihuishwe.","also":["cheti","vyeti","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Ruhusa","text":"Kanuni za nani anaweza kuona au kubadilisha nini.","also":["permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Ruhusa ndogo kabisa (Least privilege)","text":"Kumpa kila mtu au programu ufikiaji anaouhitaji kweli tu, kwa muda anaouhitaji tu.","also":["least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Udhibiti wa ufikiaji kwa majukumu (RBAC)","text":"Kutoa ufikiaji kwa jukumu, kama mtazamaji au mhariri, badala ya mtu mmoja mmoja.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Udhaifu (Vulnerability)","text":"Dosari ambayo mtu anaweza kuitumia kuingia kwa nguvu au kusababisha madhara.","also":["vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (udhaifu usiojulikana na watengenezaji)","text":"Udhaifu ambao wavamizi wanaujua kabla watengenezaji hawajapata muda wowote wa kuurekebisha.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Programu hatari (Malware)","text":"Programu yenye madhara, kama virusi, iliyotengenezwa kuharibu, kupeleleza au kuiba.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware (programu ya kutaka fidia)","text":"Programu hatari inayofunga mafaili yako na kudai pesa ili kuyafungua. Nakala za akiba nzuri ndizo kinga bora.","also":["ransomware","ransomware attack"]},{"id":"phishing","g":"sec","word":"Ulaghai wa kimtandao (Phishing)","text":"Ujumbe bandia unaojaribu kukudanganya utoe manenosiri au pesa, au kufungua kitu chenye madhara.","also":["phishing","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Udanganyifu wa kijamii (Social engineering)","text":"Kuwadanganya watu, si kompyuta, ili watoe ufikiaji, kama simu bandia kutoka “msaada wa IT”."},{"id":"firewall","g":"sec","word":"Ngome ya moto (Firewall)","text":"Mlinzi anayeamua ni trafiki ipi ya mtandao inaweza kuingia au kutoka.","also":["firewall","firewalls","ngome ya moto"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kifupi cha virtual private network: kiungo cha faragha kilichofichwa kupitia intaneti, mara nyingi hutumika kufikia mifumo ya kazi kwa usalama.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Shambulio la kuzuia huduma (DoS, DDoS)","text":"Kuijaza huduma trafiki bandia nyingi mno hadi watu halisi hawawezi kuitumia. DDoS inamaanisha inatoka kwenye kompyuta nyingi kwa wakati mmoja.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Jaribio la kuvamia kwa ruhusa (pen test)","text":"Kuajiri wataalamu rafiki kujaribu kuingia kwa nguvu, ili udhaifu upatikane kabla wavamizi halisi hawajaupata.","also":["pen test","pen testing","penetration test","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Ukaguzi wa usalama","text":"Ukaguzi makini wa jinsi kitu kilivyolindwa vizuri, dhidi ya orodha ya mazoea mazuri.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Kuchambua vitisho (Threat modelling)","text":"Kufikiria nani anaweza kushambulia kitu, kwa namna gani, na ungefanya nini kuwazuia.","also":["threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Uvujaji wa data","text":"Taarifa za faragha zinapowafikia watu wasiostahili kuwa nazo, au zinapopotea au kubadilishwa bila ruhusa.","also":["data breach","data breaches","uvujaji wa taarifa"]},{"id":"pii","g":"sec","word":"Data binafsi","text":"Taarifa yoyote kuhusu mtu anayeweza kutambuliwa, kama jina, barua pepe au mahali alipo. Pia huitwa PII.","also":["taarifa binafsi","personal data","PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Sheria ya Ulaya kuhusu data binafsi (Uingereza ina toleo lake): kusanya unachohitaji tu, kihifadhi salama, na waruhusu watu kuona au kufuta data yao.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ulinzi wa data","text":"Kutunza data binafsi ipasavyo na ndani ya sheria.","also":["data protection","data protection law","sheria ya ulinzi wa data"]},{"id":"privacypolicy","g":"sec","word":"Sera ya faragha","text":"Ukurasa wa umma unaosema ni data binafsi gani unakusanya, kwa nini, na unafanya nini nayo.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Ridhaa","text":"“Ndiyo” iliyo wazi na ya hiari ya mtu kwamba data yake itumike kwa njia fulani. Anaweza kuirudisha wakati wowote.","also":["consent","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Kuki (Cookie)","text":"Faili ndogo ambayo tovuti huhifadhi kwenye kivinjari chako kukumbuka mambo, kama kuwa umeingia. Baadhi zinahitaji ridhaa yako kwanza.","also":["kuki","cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Kupunguza ukusanyaji wa data","text":"Kukusanya na kuhifadhi data binafsi unayoihitaji kweli kwa kazi hiyo tu.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Muda wa kuhifadhi data","text":"Data huhifadhiwa kwa muda gani kabla ya kufutwa. Kuihifadhi kwa muda usiozidi unaohitajika ni salama zaidi na mara nyingi ni sheria.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Kuficha utambulisho kabisa (Anonymisation)","text":"Kubadilisha data ili kwa njia yoyote ya busara mtu asiweze tena kutambuliwa kutoka kwayo.","also":["anonymisation","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Kubadilisha utambulisho kwa misimbo (Pseudonymisation)","text":"Kubadilisha majina na maelezo mengine kwa misimbo, huku ufunguo wa kuyaunganisha tena ukihifadhiwa mahali pengine. Bado ni data binafsi.","also":["pseudonymisation","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Mkataba wa usindikaji wa data (DPA)","text":"Mkataba unaosema jinsi msambazaji anavyoweza kushughulikia data binafsi kwa niaba yako.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Tathmini ya athari ya ulinzi wa data (DPIA)","text":"Uchunguzi makini, kabla hujaanza, wa jinsi mpango wa kutumia data binafsi unavyoweza kuathiri watu na jinsi ya kupunguza hatari.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Kumbukumbu ya ukaguzi (Audit log)","text":"Rekodi ya nani alifanya nini na lini, ili vitendo viweze kukaguliwa baadaye.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Kutii kanuni (Compliance)","text":"Kufuata sheria, kanuni na viwango vinavyokuhusu, na kuweza kuonyesha kwamba unafanya hivyo.","also":["compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Kiwango cha kimataifa kinachojulikana cha kusimamia usalama wa taarifa. Kampuni zinaweza kuthibitishwa dhidi yake.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Ripoti ya Marekani, iliyokaguliwa na wakaguzi wa nje, inayoonyesha kampuni inatunza data za wateja ipasavyo.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Wakala","text":"AI inayofanya kazi yenyewe kwenye jukumu: husoma msimbo, hufanya mabadiliko, huendesha ukaguzi na kuripoti. Kazi yake bado hukaguliwa.","also":["agent","agents","mawakala"]},{"id":"token","g":"ai","word":"Tokeni","text":"Vipande vidogo vya maandishi ambavyo AI husoma na kuandika, takriban robo tatu ya neno kila kimoja. Matumizi ya AI huhesabiwa kwa tokeni, kwa hiyo tokeni chache huacha sehemu kubwa zaidi ya mpango wako ikiwa imebaki.","also":["token","tokens","tokeni"]},{"id":"hook","g":"ai","word":"Hook","text":"Amri ndogo inayojiendesha yenyewe wakati maalumu, kwa mfano kipindi cha AI kinapoanza, ili timu isikie maoni yako.","also":["hooks"]},{"id":"ai","g":"ai","word":"Akili bandia (AI)","text":"Mifumo ya kompyuta inayofanya mambo ambayo kwa kawaida tunadhani yanahitaji mtu, kama kuandika, kujibu maswali au kutambua picha.","also":["akili bandia","AI","artificial intelligence","akili mnemba"],"noTip":1},{"id":"ml","g":"ai","word":"Kujifunza kwa mashine (ML)","text":"Njia ya kuifanya kompyuta ijifunze mifumo kutokana na mifano mingi, badala ya kuipa kanuni kamili.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Modeli","text":"“Ubongo” uliofunzwa wa mfumo wa AI, uliojengwa kwa kujifunza kutokana na mifano mingi sana. Modeli hutofautiana kwa ujuzi, kasi na bei.","also":["mfano wa AI","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Modeli kubwa ya lugha (LLM)","text":"Modeli ya AI iliyofunzwa kwa kiasi kikubwa mno cha maandishi, kwa hiyo inaweza kusoma na kuandika lugha.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"AI ya kuzalisha (Generative AI)","text":"AI inayounda vitu vipya, kama maandishi, picha au msimbo, badala ya kupanga au kutambua tu.","also":["Generative AI","GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot (roboti ya mazungumzo)","text":"Programu unayozungumza nayo kwa lugha ya kila siku, kwa kuandika au kusema.","also":["chatbot","chatbots","roboti ya mazungumzo"]},{"id":"prompt","g":"ai","word":"Maelekezo kwa AI (Prompt)","text":"Unachoipa AI: swali lako au maagizo, pamoja na chochote unachoikabidhi. Maelekezo wazi zaidi kwa kawaida hupata majibu bora.","also":["prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Ufundi wa maelekezo (Prompt engineering)","text":"Ujuzi wa kuandika maelekezo yanayopata matokeo ya kuaminika na yenye manufaa.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"Maelekezo ya mfumo (System prompt)","text":"Maagizo ya nyuma ya pazia ambayo AI hupewa kabla mazungumzo hayajaanza, yanayoweka jukumu na kanuni zake. Yana uzito zaidi kuliko unachoandika.","also":["system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Muktadha (Context)","text":"Kila kitu ambacho AI inaweza kuona inapofanya kazi: maagizo, jumbe zako, mafaili iliyosoma na majibu ya awali.","noTip":1},{"id":"ctxwin","g":"ai","word":"Dirisha la muktadha","text":"Kiasi ambacho AI inaweza kukiweka akilini kwa wakati mmoja, kinachopimwa kwa tokeni. Zaidi ya hapo, sehemu za zamani huachwa au kufupishwa.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Kipindi (Session)","text":"Mazungumzo moja ya kazi na AI, kuanzia mwanzo hadi mwisho. Kipindi kipya huanza na kumbukumbu mpya.","also":["session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Kumbukumbu","text":"Maelezo ambayo AI huhifadhi kati ya vipindi, ili ikumbuke mapendeleo yako na maamuzi ya awali.","noTip":1},{"id":"hallucination","g":"ai","word":"Kubuni uongo (Hallucination)","text":"AI inaposema kitu kinachosikika kuwa na uhakika lakini ni cha kubuni au kimekosewa. Hakiki ukweli muhimu.","also":["hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Kufunza (Training)","text":"Kufundisha modeli kwa kuionyesha mifano mingi sana, kabla mtu yeyote hajaitumia.","also":["kufunza","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Data ya mafunzo","text":"Mifano ambayo modeli ilijifunza kutoka kwayo. Maarifa yake yanaishia tarehe data hiyo ilipokusanywa.","also":["training data","training set"]},{"id":"cutoff","g":"ai","word":"Tarehe ya mwisho ya maarifa","text":"Tarehe ambayo maarifa yaliyojengwa ndani ya AI yanaishia. Haitajua mambo ya baadaye isipoyatafuta.","also":["knowledge cutoff","training cutoff"]},{"id":"finetune","g":"ai","word":"Kuboresha modeli (Fine-tuning)","text":"Mafunzo ya ziada ya modeli iliyopo kwa mifano yako mwenyewe, ili iwe bora zaidi kwenye kazi moja mahususi.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Matumizi ya modeli (Inference)","text":"Modeli ya AI inapotumiwa kweli kujibu kitu, tofauti na kufunzwa.","also":["inference","model inference"]},{"id":"tooluse","g":"ai","word":"Matumizi ya zana (Tool use)","text":"AI kuweza kufanya mambo, si kuzungumza tu: kuendesha amri, kusoma mafaili au kutafuta mtandaoni, kupitia zana ambazo programu inaipa.","also":["tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Wakala msaidizi (Subagent)","text":"AI msaidizi ambaye AI mkuu humkabidhi kazi ndogo, na kupata matokeo kutoka kwake.","also":["subagent","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Mawakala wengi (Multi-agent)","text":"AI kadhaa zikifanya kazi pamoja kwenye kazi moja, kila moja na sehemu yake, kama timu ndogo.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Uhuru wa kutenda (Autonomy)","text":"Kiasi ambacho AI inaruhusiwa kufanya yenyewe kabla ya kulazimika kumuuliza mtu.","also":["autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Binadamu kwenye mchakato","text":"Kumshirikisha mtu kukagua au kuidhinisha AI inachofanya katika nyakati muhimu. Kwenye AI-gile huyo ni wewe.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Vizuizi vya usalama (Guardrails)","text":"Mipaka na ukaguzi unaoweka vitendo vya AI salama, kama kuhitaji idhini kabla chochote hakijaenda hewani. Hupunguza hatari ya makosa, lakini haviyaondoi kabisa.","also":["guardrails","guardrail"]},{"id":"rag","g":"ai","word":"Kutafuta kisha kuzalisha (RAG)","text":"Kuiruhusu AI itafute mambo kwenye nyaraka zako kabla ya kujibu, ili majibu yake yategemee ukweli wako.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Uwakilishi wa namba (Embedding)","text":"Kubadilisha maandishi kuwa orodha ya namba inayobeba maana yake, ili kompyuta ipate vitu vyenye maana zinazofanana.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Hifadhidata ya vekta (Vector database)","text":"Hifadhidata iliyojengwa kutafuta orodha hizo za namba (embeddings), kupata vitu vyenye maana inayofanana.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Njia ya pamoja ya kuchomeka zana na vyanzo vya data kwenye programu za AI, ili AI iweze kuvitumia.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Joto la modeli (Temperature)","text":"Mpangilio wa jinsi majibu ya AI yanavyothubutu. Chini hutoa majibu thabiti zaidi yanayotabirika; juu hutoa yenye utofauti zaidi. Hakuna kati ya hivyo kinachoifanya iwe sahihi kila mara.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Njia nyingi za taarifa (Multimodal)","text":"Inayoweza kufanya kazi na aina zaidi ya moja ya taarifa, kama maandishi, picha na sauti.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Tathmini (eval)","text":"Jaribio lililopangwa la jinsi AI inavyofanya vizuri kwenye mifano iliyochaguliwa, ili ulinganishe modeli au maelekezo.","also":["tathmini","evaluation","eval","evals"]},{"id":"bias","g":"ai","word":"Upendeleo (Bias)","text":"AI (au mtu) inapoegemea upande mmoja isivyo haki, mara nyingi kwa sababu ya mambo iliyojifunza.","also":["upendeleo","bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI inayowajibika","text":"Kutumia AI kwa haki, usalama na uaminifu, huku watu wakibaki kuwajibika kwa matokeo.","also":["responsible AI","ethical AI","AI ya kimaadili"]},{"id":"injection","g":"ai","word":"Kuingiza maagizo ya siri (Prompt injection)","text":"Mbinu ambapo maagizo yaliyofichwa kwenye ukurasa wa wavuti au faili hujaribu kuifanya AI ifanye kitu ambacho mtumiaji wake hakukiomba.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Kikomo cha kasi ya maombi (Rate limit)","text":"Ukomo wa maombi mangapi unaruhusiwa kutuma kwa huduma ndani ya muda uliowekwa. Ukizidi, unapaswa kusubiri.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Kikomo cha matumizi","text":"Kiasi cha kazi ya AI ambacho mpango wako unaruhusu katika kipindi, baada ya hapo husimama au hugharimu zaidi.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding (kuandika msimbo kwa maelezo)","text":"Kujenga programu hasa kwa kuieleza AI unachotaka na kuiacha iandike msimbo.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Bajeti","text":"Kiasi cha pesa kilichotengwa kwa ajili ya kitu.","also":["budget","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Makadirio ya gharama","text":"Makisio bora ya gharama ya kitu kabla hujaanza.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Faida kwa uwekezaji (ROI)","text":"Unachorudishiwa ikilinganishwa na ulichoweka. Ikiwa ni chanya, ilistahili.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Gharama kamili ya umiliki (TCO)","text":"Kila kitu ambacho kitu kinagharimu kweli katika maisha yake yote, si bei ya kununua tu: kukiendesha, msaada, masasisho na hatimaye kukistaafisha.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx na OpEx","text":"CapEx ni pesa inayotumiwa mwanzoni kwa vitu unavyovihifadhi; OpEx ni matumizi yanayoendelea, kama bili za kila mwezi.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Usajili wa malipo (Subscription)","text":"Kulipa mara kwa mara, kwa kawaida kila mwezi au mwaka, ili kuendelea kutumia kitu.","also":["subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Programu kama huduma (SaaS)","text":"Programu unayotumia mtandaoni na kulipia kwa usajili, huku mtengenezaji akiiendesha kwa ajili yako.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Lipa kadiri unavyotumia","text":"Kulipia unachotumia tu, kama kompyuta ya wingu au tokeni za AI.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Matumizi ya ziada (Overage)","text":"Matumizi zaidi ya yanayojumuishwa kwenye mpango wako, ambayo yanaweza kugharimu zaidi.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Tahadhari ya malipo","text":"Ujumbe pale matumizi ya pesa au huduma yanapofikia kiwango ulichochagua. Unakuonya, lakini si mara zote husimamisha gharama zaidi.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Kiwango cha bure","text":"Kiwango cha bure cha huduma inayolipiwa, chenye mipaka. Kinafaa kuanzia.","also":["free tier","free plan","mpango wa bure"]},{"id":"pricing","g":"money","word":"Mpango wa bei","text":"Vifurushi tofauti ambavyo huduma huuza, kila kimoja na bei na mipaka yake.","also":["pricing plan","pricing plans","price plan","mipango ya bei"]},{"id":"licence","g":"money","word":"Leseni","text":"Kanuni za jinsi unavyoweza kutumia, kunakili, kubadilisha au kushiriki kitu alichotengeneza mtu mwingine, kama programu, fonti au picha.","also":["licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Chanzo huria (Open source)","text":"Programu ambayo msimbo wake yeyote anaweza kuusoma, kuutumia na mara nyingi kuubadilisha bila malipo, chini ya kanuni za leseni yake.","also":["chanzo huria","open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Leseni ya chanzo huria","text":"Kanuni zinazokuja na msimbo wa chanzo huria. Nyingine zinakuruhusu kufanya karibu kila kitu (kama MIT); nyingine zinakuomba pia ushiriki mabadiliko yako (kama GPL).","also":["leseni za chanzo huria","open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Miliki ya kampuni (Proprietary)","text":"Inayomilikiwa na kampuni na si huru kunakiliwa au kubadilishwa. Kinyume cha chanzo huria.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Hakimiliki","text":"Haki ya kisheria ya mbunifu kudhibiti nakala za kazi yake, ikiwemo msimbo na maandishi.","also":["copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Mali ya kiakili (IP)","text":"Mawazo na ubunifu ambavyo sheria huvichukulia kuwa vinamilikiwa, kama msimbo, michoro, majina na nembo.","also":["mali ya kiakili","IP","intellectual property"]},{"id":"tos","g":"money","word":"Masharti ya huduma","text":"Kanuni unazokubali unapotumia huduma.","also":["masharti ya matumizi","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Mkataba","text":"Makubaliano yaliyoandikwa kati ya pande mbili ambayo sheria itayasimamia.","also":["mikataba","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Hati ya wigo wa kazi (SOW)","text":"Hati inayoeleza hasa kazi gani itafanywa, kufikia lini na kwa gharama gani.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Bei maalumu isiyobadilika","text":"Bei iliyokubaliwa kwa kazi nzima, bila kujali inachukua muda gani.","also":["bei maalumu","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Muda na vifaa (Time and materials)","text":"Kulipia saa zilizofanyiwa kazi kweli na vitu vilivyotumika kweli, badala ya bei iliyowekwa.","also":["time and materials","T&M"]},{"id":"invoice","g":"money","word":"Ankara","text":"Bili inayoomba malipo kwa kazi iliyofanywa au bidhaa zilizotolewa.","also":["invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Kufungiwa kwa msambazaji (Vendor lock-in)","text":"Kuondoka kwa msambazaji kunapokuwa kugumu au ghali sana hadi unakwama naye.","also":["vendor lock-in","lock-in"]},{"id":"procurement","g":"money","word":"Ununuzi wa kitaasisi (Procurement)","text":"Mchakato wa kuchagua na kununua kutoka kwa wasambazaji.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Fidia ya huduma (Service credit)","text":"Pesa kurudishiwa au punguzo unalopata pale msambazaji anapokosa kutimiza SLA yake.","also":["service credit","service credits"]}]}};
